  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'كاب كت', 'kab-kt', (SELECT id FROM categories WHERE slug='design' LIMIT 1), 'Bytedance Pte. Ltd', 'com.lemon.lvoverseas', 'https://play.google.com/store/apps/details?id=com.lemon.lvoverseas',
  'كاب كت غيّر قواعد اللعبة لما جعل تحرير الفيديو الاحترافي بمتناول أي شخص عنده موبايل وفكرة.', 'كان فيه وقت تحرير الفيديو شغلة ما بتعملها غير على كمبيوتر بقدرة عالية وبرامج غالية ومعقدة. جاء كاب كت وكسر هالمعادلة بالكامل. هلق أي شخص عنده موبايل أندرويد يقدر يجمع مقاطع فيديو، يضيف موسيقى وتأثيرات وانتقالات سلسة، ويصدّر نتيجة نهائية احترافية بجودة 4K، كل هاد بتطبيق مجاني ومبسط الاستخدام.

كاب كت من تطوير شركة Bytedance نفس الشركة يلي طورت تيك توك، وهاد واضح من التكامل الممتاز بين التطبيقين. كتير من الفيديوهات يلي بتشوفها على تيك توك تم تحريرها بكاب كت قبل رفعها، لأنو التطبيق يوفر كل الأدوات اللي تحتاجها لتقديم محتوى جذاب ومميز. التكامل المباشر مع تيك توك بيتيح لك الرفع المباشر من داخل كاب كت بضغطة زر واحدة.

المحرر الرئيسي بكاب كت مبني على خط زمني timeline واضح وسهل الفهم حتى للمبتدئين. بتقدر تستورد كل مقاطع الفيديو والصور والصوت من مكتبة الجهاز، وترتبها كيف بدك على الخط الزمني، وتقصها وتدمجها بسلاسة. فيه أدوات لضبط السرعة بشكل دقيق سواء بالتبطيء أو التسريع، وهاد بيخلي تأثيرات الحركة البطيئة أو السريعة متاحة لأي حدا.

مكتبة الانتقالات والمؤثرات بكاب كت هي من أضخم ما وجدته بتطبيقات الموبايل. فيه مئات الانتقالات المختلفة بين المقاطع، من البسيطة والكلاسيكية للانتقالات الديناميكية المعقدة. كمان فيه مكتبة ضخمة من المؤثرات البصرية والفلاتر اللونية والإضاءة، وكل هاد مجاني بالأساس مع بعض العناصر المميزة المدفوعة. بس الجزء المجاني وحده كافي لعمل محتوى احترافي بالكامل.

ميزة إزالة الخلفية تلقائياً (Chroma Key / Cutout) هي واحدة من أبرز ما يميز كاب كت. بضغطة واحدة يقدر التطبيق يزيل الخلفية من وراء الشخص بالفيديو أو الصورة، ويخليك تحط خلفية تانية بدلها. قبل ما يصير هاد متاح بالموبايل، كان يحتاج برامج احترافية ودقة عالية بالتحرير. هلق أي شخص يقدر يعمل تأثيرات ما كانت تبان إلا بالإنتاج الاحترافي.

نظام النص المتحرك بكاب كت متطور جداً. بتقدر تضيف نصوص بخطوط مختلفة، وتحركها على الشاشة، وتضيف لها ظلال وتأثيرات ضوء، وتحددها تجي بتوقيت معين من الفيديو. هاد مفيد كتير لإضافة ترجمة لفيديو، أو كتابة معلومات بالشاشة بطريقة جذابة ومنظمة. فيه كمان خاصية Auto Captions تتعرف تلقائياً على الكلام بالفيديو وتضيف ترجمة نصية متزامنة، وهاد وفّر وقت هائل على كتير منشئي المحتوى.

الصوت والموسيقى بكاب كت بنفس مستوى الفيديو. بتقدر تضيف موسيقى من مكتبة ضخمة داخل التطبيق أو من جهازك، وتتحكم بمستوى الصوت لكل عنصر بشكل مستقل، وتضيف مؤثرات صوتية متنوعة. فيه كمان Voice Changer بيغير طبيعة صوتك لأصوات مختلفة مضحكة أو إبداعية. المحتوى الكوميدي والترفيهي استفاد كتير من هاي الميزة.

كاب كت متاح على أندرويد 9.0 وما فوق، ويحتاج حوالي 205 ميغابايت. الأداء على معظم الأجهزة المتوسطة والعالية ممتاز، بس التحرير بالجودة العالية ممكن يكون ثقيل شوية على الأجهزة القديمة أو الضعيفة. التطبيق مجاني بالكامل بالميزات الأساسية مع خيار اشتراك مدفوع لميزات إضافية متقدمة.

من أكثر الاستخدامات شيوعاً لكاب كت هي تحرير فيديوهات السفر والمطاعم، الفيديوهات التعليمية، محتوى تيك توك وريلز إنستغرام، وفيديوهات الأعراس والمناسبات. صار كتير ناس يعملوا فيديوهات احترافية لمناسبات العيلة كهدية بديلة عن الألبومات الورقية، وهاد شي حلو ومميز ببيصير يتذكر على مر السنين.

التحديثات الأخيرة أضافت ميزة AI التوليدية لإنشاء خلفيات وعناصر بصرية بناءً على وصف نصي، وتحسينات على Auto Captions لدعم أفضل للغة العربية، وميزة Keyframe للتحكم الدقيق بالحركة.',
  '["محرر فيديو على خط زمني احترافي وسهل الاستخدام", "إزالة خلفية تلقائية بتقنية AI", "مكتبة ضخمة من الانتقالات والمؤثرات", "نص متحرك وعناوين ديناميكية", "Auto Captions لترجمة الكلام تلقائياً", "تصدير بجودة تصل لـ 4K"]', '["مجاني بالكامل للميزات الأساسية بدون علامة مائية قسرية", "واجهة بسيطة مناسبة للمبتدئين والمحترفين", "تكامل مباشر مع تيك توك للرفع السريع", "تحديثات مستمرة بميزات AI متقدمة"]', '["بعض الميزات المتقدمة تحتاج اشتراكاً مدفوعاً", "ثقيل شوية على الأجهزة القديمة والضعيفة"]',
  '["حمّل كاب كت من متجر جوجل بلاي", "افتح التطبيق وابدأ مشروع فيديو جديد", "استورد مقاطعك من مكتبة الجهاز", "حرّر وأضف مؤثراتك ثم صدّر الفيديو بالجودة المناسبة"]', '[{"q": "هل كاب كت يضيف علامة مائية على الفيديو؟", "a": "النسخة المجانية لا تضيف علامة مائية إجبارية على كل الفيديوهات في معظم الحالات، وبإمكانك إزالتها بسهولة من إعدادات التصدير."}, {"q": "هل أستطيع تحرير فيديو طويل على كاب كت؟", "a": "نعم، لا يوجد حد أقصى واضح لطول الفيديو في معظم الحالات، لكن الفيديوهات الطويلة جداً قد تحتاج وقتاً أطول للمعالجة."}, {"q": "هل كاب كت يدعم العربية؟", "a": "نعم، التطبيق يدعم إضافة نصوص عربية، وخاصية Auto Captions تدعم العربية في الإصدارات الحديثة."}, {"q": "ما الفرق بين كاب كت وتطبيقات التحرير الأخرى؟", "a": "كاب كت يتميز بسهولة الاستخدام مع ميزات احترافية غير متاحة في معظم المنافسين المجانيين، وتكامله مع تيك توك يجعله الخيار الأمثل لمنشئي محتوى التواصل الاجتماعي."}]', 'آخر تحديثات كاب كت أضافت أدوات AI توليدية لإنشاء خلفيات فيديو، وتحسينات على Auto Captions للعربية، وميزة CapCut AI Clip لإنشاء ريلز تلقائياً من مقاطع طويلة.',
  'تحميل كاب كت APK آخر إصدار 2026 للأندرويد | CapCut', 'حمّل كاب كت آخر إصدار APK 2026 للأندرويد مجاناً، وحرّر فيديوهاتك باحتراف بمؤثرات وأدوات AI متقدمة.', 'تحميل كاب كت, تنزيل كاب كت, CapCut APK, كاب كت للأندرويد, تحرير فيديو, CapCut 2026, تنزيل CapCut APK, كاب كت آخر إصدار, تحميل كاب كت مجاناً',
  4.8, 50394, 197158, 'published', 'مجاني',
  NOW() - INTERVAL 306 DAY, NOW() - INTERVAL 8 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'يوتيوب ميوزيك', 'ywtywb-mywzyk', (SELECT id FROM categories WHERE slug='productivity' LIMIT 1), 'Google LLC', 'com.google.android.apps.youtube.music', 'https://play.google.com/store/apps/details?id=com.google.android.apps.youtube.music',
  'يوتيوب ميوزيك هو الخيار الأمثل لمن يريد موسيقى بلا حدود مع اقتراحات ذكية تعرف ذوقك أحياناً أفضل منك.', 'لما تحكي عن الموسيقى على الإنترنت، كتير ناس بتفكر بسبوتيفاي أو أبل ميوزيك. بس في خيار ثالث قوي جداً يلي كتير ناس ما انتبهوا له كفاية: يوتيوب ميوزيك. والسبب إنو يوتيوب ميوزيك مبني على قاعدة بيانات يوتيوب الهائلة يلي بتشمل مئات الملايين من المقاطع الموسيقية، وهاد بيعطيه ميزة إنو تلاقي فيه أغاني ونسخ وتسجيلات حية ما بتلاقيها على أي منصة موسيقية تانية بالعالم.

يوتيوب ميوزيك من تطوير Google LLC، وانطلق كخدمة منفصلة سنة 2018 كبديل لـ Google Play Music يلي توقف لاحقاً. الفكرة بسيطة: تجمع خبرة يوتيوب بالمحتوى الموسيقي الواسع مع تجربة الاستماع المريحة والمنظمة بتطبيق مخصص للموسيقى فقط. والنتيجة كانت تطبيق بيجمع أفضل العالمين.

أول ما يلفت النظر بيوتيوب ميوزيك هو خاصية الاكتشاف الموسيقي. التطبيق بيتعلم من كل ما تستمع له ويبني صورة واضحة عن ذوقك الموسيقي، ثم يقترح عليك أغاني وألبومات وفنانين ما كنت لتعرفهم لو ما كان هاد النظام. صفحة Home بتتغير مع الوقت وتصبح أدق وأقرب لما تحب، وفيه قوائم تشغيل تلقائية بتُنشأ لك حسب أوقات اليوم والمناسبة.

مكتبة يوتيوب ميوزيك تشمل ما هو موجود بمنصات الستريمينغ الرسمية مضافاً إليه كل ما نشره فنانون صغار ومستقلون ومعجبون على يوتيوب. يعني لو بدك تسمع تسجيلاً نادراً لحفل حي لفنان عربي قبل عشرين سنة، احتمال كبير تلاقيه هنا ولو ما كان موجوداً على سبوتيفاي أو منصة تانية. هاد الشي بيجعله الخيار الأفضل للموسيقى العربية بكل أنواعها وأجيالها.

التطبيق بيوفر تجربة استماع ممتعة حتى بالنسخة المجانية، مع إعلانات بسيطة. النسخة المدفوعة YouTube Premium بتتيح الاستماع في الخلفية، التنزيل للاستماع بدون إنترنت، وتجربة بلا إعلانات. الاستماع في الخلفية هو أكثر ميزة يطلبها المستخدمون، لأنه بيتيح الاستماع وانت عم تستخدم تطبيقات تانية أو حتى وشاشتك مطفية.

جودة الصوت بيوتيوب ميوزيك ممتازة على الاشتراك المدفوع مع دعم للصوت عالي الجودة. حتى بالنسخة المجانية الجودة مقبولة جداً للاستماع اليومي. التطبيق كمان يدعم إرسال الصوت لمكبرات صوت ذكية وأجهزة Cast من جوجل.

قوائم التشغيل بيوتيوب ميوزيك متطورة. بتقدر تنشئ قوائتشغيل خاصة، وتشترك بقوائم تشغيل عامة من أشخاص ثانيين، والتطبيق عنده قوائم تشغيل محررية بيديرها فريق متخصص. فيه كمان خاصية استيراد قوائت تشغيل من سبوتيفاي لو كنت عم تنتقل للخدمة.

التطبيق متاح لأندرويد 8.0 وما فوق ويحتاج حوالي 72 ميغابايت فقط، وهو خفيف مقارنة بكثير من تطبيقات الموسيقى. الأداء سلس وسريع، والواجهة نظيفة ومريحة. الاستهلاك من البطارية معقول خصوصاً وقت الاستماع بالشاشة المطفية.

للمستخدم العربي، يوتيوب ميوزيك هو الخيار الأفضل لأن المكتبة العربية فيه هي الأضخم بين كل منصات الستريمينغ. من أم كلثوم وفيروز للأغاني الحديثة والنشاز الإلكتروني، كل شي موجود هنا. كتير من الأغاني العربية القديمة ما بتلاقيها إلا هنا لأنها مرفوعة على يوتيوب مو على منصات الموسيقى الرسمية.

التحديثات الأخيرة شملت تحسينات على جودة الاستماع، وخاصية Podcast دُمجت بالتطبيق لتجربة صوتية متكاملة، وواجهة Home محدّثة بتوصيات أذكى.',
  '["مكتبة موسيقية هائلة من يوتيوب والمنصات الرسمية", "اقتراحات ذكية بتتعلم من ذوقك الموسيقي", "قوائم تشغيل تلقائية وشخصية", "تسجيلات حية ونادرة غير متاحة بمنصات أخرى", "دعم Cast لمكبرات الصوت الذكية", "Podcast مدمج في التطبيق"]', '["أضخم مكتبة للموسيقى العربية بين كل المنصات", "مجاني للاستماع مع خيار مدفوع للميزات الكاملة", "تكامل ممتاز مع باقي تطبيقات جوجل", "يتيح إيجاد تسجيلات نادرة لا توجد في أي مكان آخر"]', '["الاستماع في الخلفية يحتاج اشتراكاً مدفوعاً", "الإعلانات بالنسخة المجانية قد تقطع تجربة الاستماع"]',
  '["حمّل يوتيوب ميوزيك من متجر جوجل بلاي", "سجّل دخولك بحساب جوجل", "حدد أذواقك الموسيقية من البداية لتهيئة الاقتراحات", "ابدأ الاستماع واستكشف الموسيقى العربية والعالمية"]', '[{"q": "هل يمكن الاستماع بدون إنترنت؟", "a": "نعم لكن فقط مع اشتراك YouTube Premium المدفوع الذي يتيح تنزيل الأغاني للاستماع offline."}, {"q": "هل يوتيوب ميوزيك يدعم جميع الدول العربية؟", "a": "نعم، متاح في معظم الدول العربية، وبعض ميزاته مثل الشراء والاشتراك قد تختلف من دولة لأخرى."}, {"q": "هل أستطيع نقل قائمة تشغيل سبوتيفاي ليوتيوب ميوزيك؟", "a": "نعم، فيه أدوات طرف ثالث مثل TuneMyMusic وSoundiiz تتيح نقل قوائم التشغيل بين المنصات بسهولة."}, {"q": "هل يوتيوب ميوزيك مختلف عن تطبيق يوتيوب العادي؟", "a": "نعم، يوتيوب ميوزيك مخصص للموسيقى فقط مع واجهة وأدوات مختلفة كلياً، بينما يوتيوب العادي للمحتوى العام."}]', 'آخر تحديثات يوتيوب ميوزيك شملت دمج البودكاست بالتطبيق، وتحسينات جوهرية على خوارزمية الاقتراح، وإضافة دعم الصوت بجودة أعلى للمشتركين.',
  'تحميل يوتيوب ميوزيك APK 2026 للأندرويد | YouTube Music', 'حمّل يوتيوب ميوزيك آخر إصدار APK 2026 للأندرويد واستمع لملايين الأغاني العربية والعالمية بجودة عالية.', 'تحميل يوتيوب ميوزيك, YouTube Music APK, يوتيوب ميوزيك للأندرويد, تنزيل يوتيوب ميوزيك, YouTube Music 2026, موسيقى يوتيوب, تحميل يوتيوب موسيقى',
  4.7, 22375, 48425, 'published', 'مجاني',
  NOW() - INTERVAL 127 DAY, NOW() - INTERVAL 15 DAY
);

