INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'كيبورد جوجل', 'kybwrd-jwjl', (SELECT id FROM categories WHERE slug='productivity' LIMIT 1), 'Google LLC', 'com.google.android.inputmethod.latin', 'https://play.google.com/store/apps/details?id=com.google.android.inputmethod.latin',
  'Gboard كيبورد جوجل هو لوحة المفاتيح الأذكى على أندرويد، بتكتب أسرع وأدق مع بحث جوجل مدمج.', 'ما في شي بتستخدمه أكثر على موبايلك من لوحة المفاتيح. كل رسالة، كل بحث، كل تعليق بدك فيه لوحة مفاتيح. ولو كانت لوحة المفاتيح تعبانة أو بطيئة أو ما بتعرف ذوقك بالكلام، كل يومك عالموبايل بيصير أصعب. هون يجي Gboard أو ما يُعرف بـ Google Keyboard، اللوحة الرسمية من جوجل واللي صارت المعيار اللي بتقاس عليه لوحات المفاتيح التانية.

Gboard من تطوير Google LLC وأطلق سنة 2016. خلال وقت قصير صار اللوحة المفضلة لعشرات الملايين حول العالم بسبب مجموعة ميزات ذكية بتفوق الكثير من المنافسين. التطبيق مجاني بالكامل ومتاح لأي جهاز أندرويد 8.0 وما فوق.

أول ميزة بتلفت النظر هي التصحيح التلقائي الذكي. Gboard بيتعلم من أسلوب كتابتك تدريجياً ويصبح أكثر دقة مع الوقت بتصحيح أخطائك وتوقع الكلمة اللي بدك تكتبها. بالعربية هاد مهم جداً لأن كتابة العربي على موبايل فيها أخطاء كثيرة، وGboard بيخففها بشكل ملحوظ مع الاستخدام المستمر.

الكتابة بالصوت Voice Typing من الميزات اللي بتوفر وقتاً هائلاً. بدل ما تكتب كل حرف، بتضغط على أيقونة الصوت وتحكي، وGboard بيحوّل كلامك لنص بدقة عالية. بالعربية، الدقة تحسّنت كتير بالإصدارات الأخيرة وصارت مقبولة جداً حتى للجمل الطويلة والتعبيرات اليومية.

Bحث جوجل المدمج هو ما يميز Gboard بشكل حقيقي عن كل لوحات المفاتيح الأخرى. بدون ما تترك التطبيق الي أنت فيه، بتقدر تبحث عن أي معلومة بجوجل وتشارك النتيجة مباشرة بالمحادثة. سواء كنت تبحث عن معلومة، رابط، صورة، أو حتى تحديد موقع على الخريطة، كل هاد من داخل لوحة المفاتيح مباشرة.

الكتابة بالمسح Glide Typing هي ميزة بتبدل طريقة كتابتك بالكامل. بدل ما تضغط على كل حرف بشكل منفصل، بتمرر أصبعك بين الحروف باستمرار والتطبيق بيفهم الكلمة من مسارك. بعد شوية تمرن تلاقي إنك بتكتب أسرع بكتير من قبل، والكلمات بتطلع صح بشكل مثير للإعجاب بدون ما تنظر كتير للشاشة.

مكتبة الإيموجي والـ GIF بGboard ضخمة وذكية. بتكتب في مربع البحث اللي بالإيموجي وبتلاقي ما تدور عليه بسرعة، أو بتبحث عن GIF مباشرة من اللوحة وتشاركه فوراً. هاد وفّر خطوات كتيرة كانت لازم تعملها قبل بين التطبيقات المختلفة.

Gboard بيدعم كتابة لغات متعددة بنفس اللوحة. يعني بتقدر تكتب بالعربي وبالإنجليزي وبأي لغة تانية بدون ما تغير إعدادات اللوحة بين كل لغة. التطبيق بيكتشف اللغة تلقائياً ويتكيف معها. هاد مريح جداً لمن يستخدموا لغتين أو أكثر بنفس الوقت بمحادثاتهم اليومية.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 250 ميغابايت بسبب ملفات اللغات المتعددة، لكن بمجرد التثبيت الأداء سريع جداً مع استجابة فورية لكل ضغطة. لا يأخذ بطارية ملحوظة وهو مصمم ليكون موثوقاً باستمرار.

التحديثات الأخيرة شملت ميزات AI أذكى للتصحيح التلقائي، ودعم أفضل للغة العربية واللهجات، وتخصيص شكل اللوحة وألوانها.',
  '["تصحيح تلقائي ذكي يتعلم من أسلوبك", "بحث جوجل مدمج بدون مغادرة التطبيق", "كتابة بالصوت بدقة عالية بالعربية", "Glide Typing للكتابة بالمسح السريع", "مكتبة إيموجي وGIF مع بحث ذكي", "دعم كتابة متعددة اللغات تلقائياً"]', '["مجاني بالكامل من جوجل", "الأذكى بالتصحيح التلقائي العربي", "تكامل مع جوجل بحث وخدماته", "يدعم لغات متعددة بنفس اللوحة"]', '["حجم التنزيل كبير نسبياً بسبب ملفات اللغات", "يرسل بيانات الكتابة لجوجل لتحسين التصحيح"]',
  '["حمّل Gboard من متجر جوجل بلاي", "ثبّته وافتح إعدادات الموبايل ثم اللغة والإدخال", "اختر Gboard كلوحة المفاتيح الافتراضية", "فعّل اللغة العربية من إعدادات Gboard"]', '[{"q": "كيف أفعّل الكتابة بالصوت بالعربية؟", "a": "من إعدادات Gboard اذهب لـ Voice Typing وتأكد من تفعيله، ثم اختر اللغة العربية من قائمة اللغات المتاحة."}, {"q": "كيف أضيف لغة جديدة للوحة؟", "a": "من إعدادات Gboard اختر Languages واضغط Add Keyboard ثم اختر اللغة التي تريدها."}, {"q": "هل Gboard يحفظ ما أكتبه؟", "a": "يحفظ بيانات مجهولة لتحسين التصحيح، يمكنك تعطيل هذا من الإعدادات تحت Personal Dictionary Sharing."}, {"q": "هل يمكن تغيير شكل لوحة المفاتيح؟", "a": "نعم، من Theme في إعدادات Gboard بتقدر تغير الألوان والخلفية وبعض التخصيصات البصرية."}]', 'آخر تحديثات Gboard شملت تحسينات AI على التصحيح التلقائي العربي، وميزة مقترحات الجمل الكاملة Sentence Autocomplete، وتحسينات على Voice Typing للعربية.',
  'تحميل Gboard APK 2026 للأندرويد | كيبورد جوجل العربي', 'حمّل Gboard كيبورد جوجل آخر إصدار APK 2026 للأندرويد واكتب بسرعة وذكاء بالعربية مع بحث جوجل مدمج.', 'تحميل Gboard, كيبورد جوجل APK, Gboard عربي, لوحة مفاتيح جوجل, Gboard 2026, Google Keyboard, تنزيل Gboard',
  4.1, 43822, 245986, 'published', 'مجاني',
  NOW() - INTERVAL 258 DAY, NOW() - INTERVAL 11 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'مايكروسوفت وورد', 'maykrwswft-wwrd', (SELECT id FROM categories WHERE slug='productivity' LIMIT 1), 'Microsoft Corporation', 'com.microsoft.office.word', 'https://play.google.com/store/apps/details?id=com.microsoft.office.word',
  'مايكروسوفت وورد على الموبايل هو نفس الوورد يلي تحبه على الكمبيوتر، بكل قوته وبكل مرونته.', 'أي حدا اشتغل بمكتب أو درس بجامعة أو كتب تقريراً ما بيتعرف على مايكروسوفت وورد. البرنامج الأشهر بتاريخ معالجة النصوص صار هلق متاح على موبايلك الأندرويد بكل وظائفه الأساسية التي تحتاجها يومياً.

مايكروسوفت وورد للأندرويد من تطوير Microsoft Corporation وبيدعم كل الميزات الأساسية يلي بتحتاجها لتحرير المستندات وإنشائها. من كتابة رسالة بسيطة لتقرير معقد بجداول ورسوم بيانية وتنسيق متقدم، كل هاد ممكن من موبايلك.

التنسيق المتقدم هو ما يميز وورد عن تطبيقات الكتابة البسيطة. بتقدر تطبق أنماط heading بشكل صحيح، تضيف جداول وقوائم منقطة ومرقمة، تتحكم بالمسافات والخطوط والألوان، وتضيف صور ورسوم بيانية. النتيجة النهائية مستند مهيكل ومنسق بشكل احترافي يمكن طباعته مباشرة.

التعاون الحي هو من أبرز ميزات وورد للأندرويد. لو حفظت ملفك على OneDrive أو SharePoint، فيك تشاركه مع زملاء وتشوفوا تعديلاتهم فورياً بتأشيرات مختلفة الألوان. هاد الشي حوّل العمل الجماعي على المستندات من عملية مملة ومربكة لتعاون سلس وفعال حتى لو كان الفريق في دول مختلفة.

خاصية التتبع Track Changes مهمة جداً في البيئات المهنية والأكاديمية. بتقدر تشغلها وكل تعديل يصير على المستند بيتسجل باسم الشخص وتاريخ التعديل، وبتقدر قبوله أو رفضه لاحقاً. هاد مفيد جداً للمدراء يلي بيراجعوا تقارير موظفيهم أو للأكاديميين يلي يتعاملوا مع تصويبات الأبحاث.

القوالب Templates بوورد الأندرويد متعددة وبتغطي كتير من الاستخدامات. سيرة ذاتية، رسالة رسمية، تقرير أعمال، اقتراح مشروع، كل هاد فيه قوالب جاهزة بتعديلها بسهولة وتحصل على نتيجة احترافية بوقت قياسي. القوالب موجودة بلغات متعددة تشمل العربية.

تطبيق وورد الأندرويد متاح للاستخدام الأساسي مجاناً لكن الميزات المتقدمة تحتاج اشتراك Microsoft 365. للأجهزة بحجم شاشة 10.1 إنش أو أصغر، معظم الميزات مجانية. للأجهزة الأكبر أو الاستخدام التجاري المكثف بتحتاج الاشتراك.

التطبيق متاح على أندرويد 10.0 وما فوق ويحتاج حوالي 350 ميغابايت. الأداء على الأجهزة الحديثة ممتاز والاستجابة سريعة. التزامن مع OneDrive أوتوماتيكي ما بتحتاج تحفظ يدوياً كل شوية.

من الميزات المفيدة جداً هي إمكانية فتح وتعديل ملفات وورد المرسلة بالإيميل أو واتساب مباشرة بالتطبيق، والحفظ يصير على OneDrive أو الجهاز حسب ما تفضل. كمان فيه دعم ممتاز لملفات PDF يلي بتقدر تعدل عليها أو تحولها لوورد.

التحديثات الأخيرة شملت دمج Copilot AI للمساعدة بكتابة المستندات وتلخيصها، وتحسينات جوهرية على دعم اللغة العربية والكتابة من اليمين لليسار.',
  '["تحرير مستندات وورد بتنسيق متقدم", "تعاون حي مع الفريق عبر OneDrive", "قوالب احترافية بالعربية والإنجليزية", "Track Changes لتتبع التعديلات", "دعم ملفات PDF وتحويلها", "Copilot AI للمساعدة بالكتابة"]', '["التوافق الكامل مع ملفات Word على الكمبيوتر", "واجهة مألوفة لمستخدمي Office", "تعاون حي ممتاز مع Microsoft 365", "دعم قوي للعربية والكتابة RTL"]', '["الميزات المتقدمة تحتاج اشتراك Microsoft 365", "حجم التطبيق كبير نسبياً 350 ميغابايت"]',
  '["حمّل مايكروسوفت وورد من متجر جوجل بلاي", "سجّل دخولك بحساب Microsoft أو أنشئ واحداً مجاناً", "ابدأ مستنداً جديداً أو افتح ملفاً موجوداً", "خصص لغة الكتابة لتكون العربية من الإعدادات"]', '[{"q": "هل مايكروسوفت وورد مجاني على الأندرويد؟", "a": "نعم للاستخدام الأساسي على الأجهزة حتى 10.1 إنش. الميزات المتقدمة وللأجهزة الأكبر تحتاج Microsoft 365."}, {"q": "هل يمكن فتح ملفات وورد بالأندرويد؟", "a": "نعم، تفتح وتحرر وتحفظ ملفات .doc و.docx بالكامل بدون أي مشكلة في التوافق."}, {"q": "هل يمكن العمل offline على مايكروسوفت وورد؟", "a": "نعم، يمكنك إنشاء وتحرير المستندات offline وبمجرد الاتصال بالإنترنت تتزامن التغييرات تلقائياً."}, {"q": "كيف أشارك مستنداً مع حدا ثاني للتعاون؟", "a": "احفظ الملف على OneDrive ثم اضغط Share من داخل التطبيق وأضف إيميل الشخص وحدد صلاحياته."}]', 'آخر تحديثات وورد الأندرويد شملت دمج Microsoft Copilot AI لإنشاء وتلخيص المستندات، وتحسينات جوهرية على الكتابة العربية وتصيير RTL، وواجهة محدّثة.',
  'تحميل مايكروسوفت وورد APK 2026 للأندرويد | Microsoft Word', 'حمّل مايكروسوفت وورد آخر إصدار APK 2026 للأندرويد وحرّر مستنداتك باحتراف مع دعم كامل للعربية.', 'تحميل مايكروسوفت وورد, Microsoft Word APK, وورد أندرويد, تنزيل وورد, Word 2026, تحميل Word مجاناً, مايكروسوفت وورد للموبايل',
  4.7, 30918, 140574, 'published', 'مجاني',
  NOW() - INTERVAL 6 DAY, NOW() - INTERVAL 28 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'ون درايف', 'wn-drayf', (SELECT id FROM categories WHERE slug='productivity' LIMIT 1), 'Microsoft Corporation', 'com.microsoft.skydrive', 'https://play.google.com/store/apps/details?id=com.microsoft.skydrive',
  'ون درايف هو الجسر الذكي بين أجهزتك كلها، ملفاتك تنتقل بسلاسة من الموبايل للكمبيوتر وبالعكس.', 'لو كنت مستخدم Microsoft 365 أو Windows، ون درايف ما هو خيار هو جزء لا ينفصل من حياتك الرقمية. التخزين السحابي من مايكروسوفت الذي صار المرافق الأمين لملايين المستخدمين حول العالم الذين يعملون ضمن بيئة Microsoft.

ون درايف من تطوير Microsoft Corporation وأطلق تحت اسم SkyDrive قبل تغيير اسمه. يوفر 5 غيغابايت تخزين مجاني لكل مستخدم، مع باقات إضافية مدفوعة أو مجانية مع Microsoft 365. يلي بيشتري Office365 أو Microsoft 365 بيحصل على 1 تيرابايت تخزين مجاني، وهاد ضخم جداً بالنسبة للاستخدام الشخصي والمهني معاً.

التكامل مع تطبيقات Office هو ما يميز ون درايف بشكل كبير. كل ملف تنشئه بوورد أو إكسل أو باور بوينت يُحفظ على ون درايف تلقائياً إذا فعّلت هيك الإعدادات. وبمجرد ما تفتح نفس الحسابة على جهاز ثاني، الملفات موجودة تماماً كما تركتها آخر مرة. هاد التنسيق السلس يوفر وقتاً وجهداً هائلاً بالعمل اليومي.

النسخ الاحتياطي التلقائي للصور والفيديو هي ميزة من أكثر ما يقدمها ون درايف فائدة. بمجرد التفعيل، كل صورة تصورها ترفع على ون درايف فوراً عبر الواي فاي. يعني لو ضاع موبايلك أو انكسر، صورك كلها محفوظة بالسحابة وترجعلك بمجرد تسجيل الدخول من جهاز جديد. هاد أنقذ كتير ناس من خسارة ذكريات لا تعوض.

مشاركة الملفات بون درايف مرنة وسهلة. بتقدر تشارك ملف أو مجلد بأي شخص عبر رابط يمكنك تحديد صلاحياته وصلاحية وصوله لأجل معين. كمان بتقدر تشارك مع أشخاص محددين بإيمايلاتهم وتتحكم بصلاحياتهم. المشاركة مع الفريق بالعمل خاصة إذا كان الكل يستخدم Microsoft 365 تصبح تعاوناً فعالاً جداً.

ون درايف بيدعم الوصول offline للملفات المحددة. بتقدر تحدد الملفات أو المجلدات يلي بدك تكون متاحة بدون إنترنت، والتطبيق بيحمّلها للجهاز. وبمجرد عودة الإنترنت كل التغييرات بتتزامن تلقائياً.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 120 ميغابايت. الأداء سريع والواجهة نظيفة ومنظمة. يستهلك بيانات معقولة وقت التزامن ويمكنك تخصيصه ليزامن فقط على الواي فاي.

من الميزات المهمة هي التاريخ الكامل للملف. بتقدر ترجع لأي نسخة سابقة من ملف حرّرته بالخطأ أو بدك ترجعله. هاد أنقذ كتير ناس من فقدان شغل مهم بسبب حذف خاطئ أو تعديل غير مرغوب به.

للمستخدمين الذين يعملون بـ Windows 11، ون درايف مدمج بالكامل مع نظام التشغيل وأي ملف بتحفظه بمجلد ون درايف على الكمبيوتر يتزامن مباشرة مع التطبيق على الموبايل. هيك ما في حاجة لنقل الملفات يدوياً أبداً.

التحديثات الأخيرة شملت دمج Copilot AI لتلخيص وتحليل الملفات، وتحسينات على سرعة التزامن، وواجهة محدّثة بتصميم Fluent Design.',
  '["5 غيغابايت مجانية مع زيادة مع Microsoft 365", "نسخ احتياطي تلقائي للصور والفيديو", "تكامل كامل مع تطبيقات Office", "مشاركة ملفات مرنة بروابط أو صلاحيات محددة", "تاريخ الملفات للرجوع لنسخ سابقة", "وصول offline للملفات المحددة"]', '["تكامل لا يضاهى مع بيئة Microsoft كاملة", "1 تيرابايت مجاناً مع Microsoft 365", "نسخ احتياطي تلقائي للصور بدون تدخل", "تاريخ الملفات ينقذ من الأخطاء"]', '["المساحة المجانية 5 غيغابايت أقل من المنافسين", "الاستفادة الكاملة تحتاج مجموعة Microsoft 365"]',
  '["حمّل ون درايف من متجر جوجل بلاي", "سجّل دخولك بحساب Microsoft", "فعّل النسخ الاحتياطي التلقائي للصور", "ابدأ برفع ملفاتك وتنظيمها بمجلدات"]', '[{"q": "هل ون درايف يمكن استخدامه بدون Microsoft 365؟", "a": "نعم، يوفر 5 غيغابايت مجانية لأي حساب Microsoft بدون اشتراك، والميزات الأساسية كلها متاحة."}, {"q": "كيف أزيد مساحة ون درايف المجانية؟", "a": "يمكنك الترقية لخطة Microsoft 365 Personal أو Family التي تشمل 1 تيرابايت لكل مستخدم."}, {"q": "هل ون درايف آمن لحفظ ملفاتي الحساسة؟", "a": "نعم، يوفر تشفيراً متقدماً وحماية بالمصادقة متعددة العوامل، وهو مبني على نفس بنية Microsoft Azure الأمنية."}, {"q": "هل يمكن الوصول لون درايف من الكمبيوتر؟", "a": "نعم، من خلال onedrive.live.com أو التطبيق المدمج بـ Windows، وكذلك من Mac وLinux."}]', 'آخر تحديثات ون درايف شملت دمج Microsoft Copilot لتلخيص وتحليل الملفات، وتحسينات على التزامن السريع، وتصميم Fluent Design محدّث.',
  'تحميل ون درايف APK 2026 للأندرويد | OneDrive Microsoft', 'حمّل ون درايف آخر إصدار APK 2026 للأندرويد مجاناً واحفظ ملفاتك بالسحابة مع تكامل كامل مع Office.', 'تحميل ون درايف, OneDrive APK, ون درايف أندرويد, تخزين مايكروسوفت, OneDrive 2026, تنزيل OneDrive مجاناً',
  4.5, 4425, 10210, 'published', 'مجاني',
  NOW() - INTERVAL 214 DAY, NOW() - INTERVAL 13 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'أدوبي لايتروم', 'adwby-laytrwm', (SELECT id FROM categories WHERE slug='design' LIMIT 1), 'Adobe Inc.', 'com.adobe.lrmobile', 'https://play.google.com/store/apps/details?id=com.adobe.lrmobile',
  'أدوبي لايتروم هو المحرر الذي حوّل الفوتوغرافيا الاحترافية من الكمبيوتر إلى راحة يدك.', 'كان المصورون المحترفون يقضون ساعات طويلة أمام الكمبيوتر لتحرير صورهم على أدوبي لايتروم. هلق هيك لم يعد ضرورياً بالمطلق. أدوبي لايتروم للأندرويد جلب نفس الأدوات الاحترافية لموبايلك، وصار كتير مصورين يعالجون الصور مباشرة على الجهاز بنتائج ما تختلف عن الكمبيوتر.

أدوبي لايتروم من تطوير Adobe Inc. الشركة العملاقة اللي وراء برامج التصميم والتحرير الأشهر بالعالم. النسخة الموبايل أطلقت سنة 2015 وتطورت بشكل مستمر لتصبح اليوم الأقوى بفئتها على متجر أندرويد. المصور الهاوي والمحترف كلاهما بيجدان فيه ما يحتاجانه.

التحكم بالضوء والألوان هو قلب لايتروم. أدوات Exposure وContrast وHighlights وShadows وWhites وBlacks بتعطيك تحكماً دقيقاً شبه مستحيل بتطبيقات التحرير العادية. بتقدر تضبط الإضاءة بكل مناطق الصورة بشكل مستقل، وتعزز تفاصيل الظلال بدون حرق الأجزاء المضيئة. هيك النوع من التحرير كان حكراً على المحترفين بالكمبيوتر.

نظام المنحنيات Curves هو أداة المحترفين الحقيقيين. بتعطيك تحكماً مطلقاً بتوزيع الألوان والإضاءة في الصورة بشكل يفوق كل الأدوات الأخرى. كتير مصورين محترفين قالوا إن لايتروم موبايل أعطاهم نفس نتائج الكمبيوتر بدقيقة الجهاز.

المسبقات Presets هي ميزة تبسّط التحرير بشكل هائل. بتقدر تنشئ مسبقاتك الخاصة يلي بتطبق مجموعة من التعديلات بضغطة واحدة، أو تستخدم مسبقات جاهزة من أدوبي أو من مجتمع المصورين. هاد بيعطيك أسلوباً موحداً لكل صورك ويوفر وقتاً هائلاً لو كنت تحرر مجموعة صور كبيرة.

دعم ملفات RAW هو ما يجعل لايتروم في مصاف آخر من التطبيقات. كتير كاميرات أندرويد الآن تلتقط صوراً RAW تحتوي على بيانات أكثر بكثير من JPEG، وبتحتاج معالجة. لايتروم يفتح ملفات RAW ويعطيك تحكماً كاملاً بكل بيانات الصورة مو بس بالنتيجة المضغوطة.

التطبيق متاح على أندرويد 9.0 وما فوق ويحتاج حوالي 180 ميغابايت. الأداء على الأجهزة الحديثة رائع مع معالجة سريعة حتى لملفات RAW الكبيرة. الميزات الأساسية مجانية، والمزيد من الأدوات المتقدمة تحتاج اشتراك Creative Cloud.

المزامنة مع Creative Cloud تعني إن تعديلاتك على الموبايل تظهر فوراً على الكمبيوتر والعكس. لو بدأت مشروعاً بالموبايل وبدك تكمله بدقة أكبر على الكمبيوتر، كل شي محفوظ وجاهز بدون خطوات إضافية. هيك يصير الموبايل امتداداً طبيعياً للعمل الإبداعي لا بديلاً منعزلاً.

ميزة AI Select Subject/Sky من الإضافات الذكية الرائعة. بضغطة واحدة التطبيق يحدد الشخص بالصورة أو السماء ويتيح لك تعديلهم بشكل مستقل دون التأثير على باقي الصورة. هيك النوع من التحديد الدقيق كان يحتاج دقائق من العمل اليدوي قبل وجود الـ AI.

التحديثات الأخيرة شملت أدوات AI جديدة للإزالة والتعبئة الذكية، وتحسينات على دعم HDR، وواجهة محسّنة للتحرير على الشاشات الكبيرة.',
  '["تحرير احترافي بأدوات Curves وHSL والإضاءة المتقدمة", "دعم كامل لملفات RAW", "نظام مسبقات Presets قابل للتخصيص", "AI لانتقاء الأشخاص والسماء تلقائياً", "مزامنة مع Creative Cloud", "تحرير غير مدمر يحفظ الصورة الأصلية"]', '["الأقوى للتحرير الاحترافي على الموبايل", "دعم RAW لأقصى جودة ممكنة", "مزامنة سلسة مع لايتروم الكمبيوتر", "الميزات الأساسية مجانية"]', '["الأدوات المتقدمة تحتاج اشتراك Creative Cloud المدفوع", "بطيء قليلاً على الأجهزة القديمة مع ملفات RAW"]',
  '["حمّل أدوبي لايتروم من متجر جوجل بلاي", "أنشئ حساب Adobe المجاني أو سجّل دخولك", "استورد صورك من مكتبة الجهاز", "ابدأ بالتعديل واكتشف أدوات الضوء والألوان"]', '[{"q": "هل لايتروم موبايل مجاني؟", "a": "الميزات الأساسية مجانية. الأدوات المتقدمة مثل الكتابة الاحترافية والمزامنة الكاملة تحتاج اشتراك Adobe Creative Cloud."}, {"q": "هل تعديلاتي على الموبايل تظهر على الكمبيوتر؟", "a": "نعم، بشرط تفعيل Adobe Creative Cloud Sync، كل التعديلات تتزامن بين الأجهزة فوراً."}, {"q": "هل لايتروم يدعم الكاميرا RAW؟", "a": "نعم، يدعم RAW من معظم الكاميرات والهواتف الذكية الحديثة التي تلتقط بصيغة DNG أو RAW الخاص."}, {"q": "هل يمكن مشاركة الصور المعدّلة مباشرة؟", "a": "نعم، بتقدر تصدّر الصورة بالجودة والحجم اللي تريده ثم تشاركها مباشرة لواتساب أو إنستغرام أو أي تطبيق ثاني."}]', 'آخر تحديثات لايتروم شملت أدوات AI للإزالة الذكية وملء الخلفية، ودعم HDR محسّن، وأداء أسرع على الأجهزة الحديثة.',
  'تحميل أدوبي لايتروم APK 2026 للأندرويد | Adobe Lightroom', 'حمّل أدوبي لايتروم آخر إصدار APK 2026 للأندرويد وحرّر صورك باحتراف مع أدوات ضوء وألوان متقدمة.', 'تحميل لايتروم, Adobe Lightroom APK, لايتروم للأندرويد, تحرير صور احترافي, Lightroom 2026, تنزيل Lightroom مجاناً',
  4.7, 42645, 170228, 'published', 'مجاني',
  NOW() - INTERVAL 75 DAY, NOW() - INTERVAL 3 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'كلاش أوف كلانز', 'klash-awf-klanz', (SELECT id FROM categories WHERE slug='games' LIMIT 1), 'Supercell', 'com.supercell.clashofclans', 'https://play.google.com/store/apps/details?id=com.supercell.clashofclans',
  'كلاش أوف كلانز اللعبة يلي بتبني قريتك وتحارب العالم، وجدت لها مكاناً دائماً على كل موبايل منذ 2012.', 'في سنة 2012، طلعت لعبة بسيطة الشكل من شركة فنلندية صغيرة اسمها Supercell، وما كان يتوقع أحد إنها رح تصير من أكثر الألعاب إدماناً وإيراداً بتاريخ الألعاب على الموبايل. هاي اللعبة هي Clash of Clans، أو كما يسميها الجميع بالعربية كلاش.

كلاش من تطوير شركة Supercell الفنلندية، يلي مشهورة بألعابها البسيطة اللي بتجذب ملايين اللاعبين عالمياً. اللعبة مجانية للتنزيل مع مشتريات داخلية اختيارية، وكثير من اللاعبين يصلون لمستويات عالية جداً بدون إنفاق أي قرش.

مبدأ اللعبة بسيط وعميق بنفس الوقت. بتبدأ بقرية فارغة وبناء أولي بسيط. تدريجياً بتبني مبانيك، بتطور جيشك، بتجمع الموارد. وبنفس الوقت بتنضم لقبيلة Clan مع لاعبين آخرين وبتقاتلوا مع بعض ضد قبائل تانية. هيك البناء والحرب والتعاون بيتشابكوا مع بعض ليعطوك تجربة ما بتقدر تتركها بسهولة.

نظام القبائل هو أحد أهم عناصر اللعبة. بتنضم لقبيلة مع 50 لاعب ثاني، وبتتواصلوا وبتتنسقوا للحروب القبلية. حروب القبائل هي حيث اللعبة تصل لقمة إثارتها، لأنك مو بس تحارب بلاعب تاني، بل أنت جزء من فريق متنسق له استراتيجية مشتركة. الانتصار فيها يعطي إحساساً جماعياً رائعاً.

المبارزات League Wars وبطولات Clan War Leagues أضافت بُعداً تنافسياً عميقاً للعبة. اللاعبون المحترفون يستثمرون وقتاً كبيراً في التخطيط لهجماتهم وتطوير جيوشهم. يوتيوب وتيك توك ممتلئان بمحتوى ترفيهي وتعليمي عن الكلاش من لاعبين عرب أنجحوا قبائلهم.

التطوير الاستراتيجي للقرية هو جوهر اللعبة. كل مبنى ترفعه درجة يستغرق وقتاً حقيقياً قد يمتد لساعات أو أيام. هاد التدرج البطيء هو ما يجعل اللعبة تُمسك باللاعبين لسنوات، لأنه دائماً في شي تطوره وتحصل عليه. بعض اللاعبين يلعبون الكلاش منذ أكثر من عشر سنوات ولا يزالون يجدون أشياء جديدة.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 350 ميغابايت. اللعبة تحتاج إنترنت للعب لأنها أونلاين بالكامل. الأداء ممتاز على الأجهزة المتوسطة والعالية، والتحديثات منتظمة كل ثلاثة أشهر تقريباً بمحتوى جديد وأبطال وبنايات.

للمستخدم العربي، الكلاش عنده مجتمع عربي ضخم جداً. كتير قبائل عربية من العيار الثقيل على مستوى عالمي، وعرب كتير وصلوا للمستوى الأعلى Legendary League. القنوات العربية على يوتيوب تعليمياً ومسلياً حول الكلاش من الأكثر مشاهدة.

نظام الـ Builder Base أضاف بُعداً ثانياً للعبة حيث قرية موازية بآليات مختلفة ولاعبون مختلفون، وهاد وفّر محتوى إضافياً لمن انتهى من كل شيء بالقرية الرئيسية.

التحديثات الأخيرة شملت تحسينات على نظام الهجوم، وبطل جديد Super Witch، وتوازنات للجيوش والمبنى، وتحسينات على أداء اللعبة عالأجهزة المتوسطة.',
  '["بناء وتطوير قرية استراتيجية متكاملة", "نظام قبائل للتعاون في الحروب", "حروب قبائل تنافسية وبطولات League", "جيوش متنوعة وأبطال قابلون للترقية", "محتوى متجدد كل ثلاثة أشهر", "Builder Base للعب مزدوج"]', '["مجانية ويمكن الوصول لمستويات عالية بدون دفع", "مجتمع عربي ضخم وقبائل قوية", "تحديثات منتظمة بمحتوى جديد", "عنصر تعاوني قوي مع القبائل"]', '["أوقات البناء الطويلة قد تحبط اللاعبين الجدد", "تحتاج إنترنت دائم للعب"]',
  '["حمّل كلاش أوف كلانز من متجر جوجل بلاي", "افتح اللعبة واتبع مرحلة التعليم الأولى", "ابنِ قريتك الأولى وطوّر مبانيها", "انضم لقبيلة عربية لتحصل على دعم من لاعبين أكثر خبرة"]', '[{"q": "هل كلاش أوف كلانز مجانية؟", "a": "نعم، التنزيل والأساسيات مجانية. الجواهر Gems يمكن شراؤها لتسريع التطوير لكنها ليست ضرورية للاستمتاع باللعبة."}, {"q": "كيف أجد قبيلة عربية جيدة؟", "a": "ابحث في Clan Search باللغة العربية أو في مجتمعات الكلاش على تيليجرام وواتساب العربية للإحالات."}, {"q": "هل يمكن استعادة قريتي لو غيرت الجهاز؟", "a": "نعم، ربط القرية بحساب Supercell ID أو جوجل يحفظها ويتيح الاسترداد من أي جهاز."}, {"q": "كم وقت يستغرق الوصول للمستوى الأعلى TH15؟", "a": "بدون رصيد قد يستغرق سنتين أو أكثر حسب معدل اللعب اليومي، وهيك يصمم الكلاش ليبقى معك طويلاً."}]', 'آخر تحديثات كلاش أوف كلانز شملت إضافة Town Hall 16 بمبانٍ وجيوش جديدة، وتوازنات شاملة للألياء، وتحسينات على واجهة القرية.',
  'تحميل كلاش أوف كلانز APK 2026 للأندرويد | Clash of Clans', 'حمّل كلاش أوف كلانز آخر إصدار APK 2026 للأندرويد مجاناً وابنِ قريتك وانضم لقبائل المعارك.', 'تحميل كلاش أوف كلانز, Clash of Clans APK, كلاش للأندرويد, تنزيل كلاش, COC 2026, كلاش أوف كلانز مجاناً',
  4.3, 79081, 192827, 'published', 'مجاني',
  NOW() - INTERVAL 20 DAY, NOW() - INTERVAL 14 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
