INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'سابواي سيرف', 'sabway-syrf', (SELECT id FROM categories WHERE slug='games' LIMIT 1), 'SYBO Games', 'com.kiloo.subwaysurf', 'https://play.google.com/store/apps/details?id=com.kiloo.subwaysurf',
  'سابواي سيرف اللعبة التي أدمنتها أصابعك بحركة لا تتوقف، وعالم يتجدد كل أسبوع بمدينة جديدة.', 'إذا كنت بتبحث عن لعبة تقضي فيها دقائق ممتعة في أي وقت وأي مكان بدون التزام أو تعقيد، سابواي سيرف هي الجواب المثالي. هي ربما أشهر لعبة Endless Runner على الموبايل، وتثبت وجودها منذ 2012 على الرغم من كل المنافسين الذين جاؤوا وذهبوا.

سابواي سيرف من تطوير SYBO Games الدنماركية وKiloo. ببساطة متناهية: شخصية تركض تلقائياً على سكة الأولى الحديدية وأنت تتحكم بها بالتمرير يساراً ويميناً وأعلى وأسفل لتتجنب العوائق. اللعبة تزداد سرعة كلما استمريت وكلما جمعت أكثر.

بساطة التحكم هي سر النجاح. لا أزرار تشتيت، لا قائمة معقدة. تمرير واحد لليمين أو اليسار يغير المسار، تمرير للأعلى يقفز، للأسفل ينزلق. بعد دقيقة تكون متقناً للأساسيات، وبعد ذلك الأمر كله عن ردة الفعل والتركيز.

عالم اللعبة يتجدد كل أسبوع. SYBO تطلق أحداثاً أسبوعية بمدن مختلفة من العالم: دبي، القاهرة، باريس، طوكيو، لندن وغيرها الكثير. كل مدينة بثيم بصري مختلف وشخصيات حصرية ومكافآت خاصة. هيك ما تشعر بالملل لأن البيئة المرئية تتغير باستمرار.

جمع النقاط والرموز هو هدف اللعبة الرئيسي. بتجمع عملات ذهبية لشراء شخصيات وزوارق جديدة، ورموز Weekly Hunt خاصة بالحدث الأسبوعي. اكتمال المجموعة الأسبوعية يعطيك مكافأة الحدث. هيك الهدف التراكمي المستمر يخليك ترجع كل يوم.

نظام الشخصيات والزوارق واسع جداً. فيه عشرات الشخصيات بتصميمات متنوعة وشخصيات موسمية مرتبطة بالأحداث الخاصة مثل رمضان وعيد الميلاد والصيف. كل زورق كمان بمزايا خاصة مثل المغناطيس وضعف التصادم وغيرها.

التطبيق متاح على أندرويد 5.1 وما فوق ويحتاج حوالي 220 ميغابايت. الأداء ممتاز حتى على الأجهزة القديمة بفضل تصميمها الخفيف. اللعبة مجانية بالكامل مع مشتريات اختيارية للشخصيات والزوارق والعملات.

سابواي سيرف من أنجح الألعاب على الإطلاق في تقديم تجربة ممتعة ومُرضية بدون ضغط أو إحباط. ما في خسارة دائمة، ما في رسوم دخول لمستوى معين، بس أنت وأرقامك الشخصية.

اللعبة وصلت لأكثر من 3 مليار تنزيل وهو رقم يجعلها من أكثر الألعاب تنزيلاً بتاريخ الموبايل. مجتمعها العربي واسع وكثيرون يتنافسون على أعلى الأرقام في أوضاع اللعب المختلفة.

التحديثات الأخيرة شملت مدينة جديدة وشخصيات حصرية موسمية وتحسينات على الأداء.',
  '["Endless Running بسيط وإدماني", "أحداث أسبوعية بمدن حول العالم", "شخصيات وزوارق متنوعة بمزايا مختلفة", "تحديات يومية وأسبوعية", "أوضاع لعب متعددة", "مجاني كلياً بمشتريات اختيارية"]', '["مثالية للوقت القصير في أي مكان", "مجانية بالكامل للاستمتاع الأساسي", "تجديد أسبوعي يمنع الملل", "خفيفة تعمل على الأجهزة القديمة"]', '["بعض الشخصيات الحصرية مدفوعة فقط", "بسيطة جداً لمن يريد عمقاً استراتيجياً"]',
  '["حمّل سابواي سيرف من متجر جوجل بلاي", "افتح اللعبة وابدأ مباشرة بدون إعداد", "تعلم الحركات الأربع خلال دقيقة", "شارك في الأحداث الأسبوعية لجمع المكافآت"]', '[{"q": "هل سابواي سيرف تعمل بدون إنترنت؟", "a": "نعم، تعمل offline تماماً بعد التنزيل الأول، لكن الأحداث الأسبوعية تحتاج إنترنت للتحديث."}, {"q": "كيف أحصل على شخصيات مجاناً؟", "a": "من خلال استكمال مجموعات الأحداث الأسبوعية ومهام التحدي اليومية ومكافآت الـ Mystery Box المجانية."}, {"q": "هل يمكن التنافس مع الأصدقاء؟", "a": "نعم، بتقدر تربط لعبتك بفيسبوك وترى نقاط أصدقائك في Leaderboard وتتنافس معهم."}, {"q": "كيف أحسّن نتيجتي؟", "a": "استخدم زورق المغناطيس لجمع العملات أسرع، وأتقن القفز بين الخطوط بذكاء مسبق لا عشوائياً."}]', 'آخر تحديثات سابواي سيرف شملت مدينة مكسيكو سيتي الجديدة وشخصيات موسمية حصرية وتحسينات على الأداء وتوهج الرسوم.',
  'تحميل سابواي سيرف APK 2026 للأندرويد | Subway Surfers', 'حمّل سابواي سيرف آخر إصدار APK 2026 للأندرويد مجاناً والعب اللعبة الأشهر للتسلية السريعة.', 'تحميل سابواي سيرف, Subway Surfers APK, سابواي سيرف للأندرويد, تنزيل Subway Surfers, سابواي سيرف 2026, تحميل سابواي سيرف مجاناً',
  4.2, 46443, 96244, 'published', 'مجاني',
  NOW() - INTERVAL 357 DAY, NOW() - INTERVAL 6 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'تمبل رن 2', 'tmbl-rn-2', (SELECT id FROM categories WHERE slug='games' LIMIT 1), 'Imangi Studios', 'com.imangi.templerun2', 'https://play.google.com/store/apps/details?id=com.imangi.templerun2',
  'تمبل رن 2 العدو المتعب والمثير الذي لا يتوقف، جرّب تمر دقيقة واحدة بدون سقوط وستعرف سر إدمانها.', 'قبل سابواي سيرف وقبل أي Endless Runner على الموبايل، كان تمبل رن هو المرجع. ولما أطلق تمبل رن 2 سنة 2013 رفع السقف بشكل هائل. اليوم لا تزال تجربة اللعبة طازجة وجذابة رغم السنوات الطويلة، وهيك يكون الإبداع الحقيقي.

تمبل رن 2 من تطوير Imangi Studios وهو المطور المستقل الذي خلق النسخة الأصلية في عام 2011. النجاح الهائل للجزء الأول دفع لإطلاق الجزء الثاني بجرافيكس محسّنة وبيئات جديدة وميكانيكيات إضافية مع الحفاظ على البساطة الأساسية التي جعلت الأصلية أيقونة.

المشهد الافتراضي مبهج. شخصيتك تركض على جسور خشبية وأقواس معمارية فوق أدغال خضراء، مع أصوات مؤثرة وموسيقى مثيرة. البيئة المرئية محسّنة جداً عن الجزء الأول مع تأثيرات ضوء وظل تعطي إحساساً بالعمق والاندماج.

التحكم بالإمالة المنمّط هو ما يميز تمبل رن 2. إضافة للتمرير الأفقي والعمودي، بتقدر تمايل الجهاز لتتحكم بالمسار في الممرات المنحنية. هيك التحكم يعطي تجربة أكثر واقعية وتحدياً من الألعاب التي تعتمد على التمرير فقط.

ميزة الطحّان Minecart أضافت تنوعاً مميزاً. في مقاطع معينة تقفز على عربة معدنية تسرع على قضبان ويتحول التحكم لتجنب العقبات بحركة مختلفة. هيك تغيير في ميكانيكية اللعب وسط الجري يمنع الروتين ويبقيك متيقظاً.

الشخصيات والقدرات الخاصة تضيف متعة تجميعية. كل شخصية بمزايا تختلف قليلاً، وبتقدر تطور قدراتها بالعملات التي تجمعها. القدرات مثل المغناطيس والدروع والنقاط المضاعفة تعطيك ميزة في الجري الأطول.

اللعبة مجانية بالكامل مع مشتريات اختيارية للعملات والشخصيات. بدون أي إنفاق يمكنك الاستمتاع الكامل باللعبة وتطوير كل ما تحتاجه بالتراكم التدريجي.

التطبيق متاح على أندرويد 5.0 وما فوق ويحتاج 110 ميغابايت فقط، وهو خفيف جداً يعمل على حتى الأجهزة القديمة نسبياً. الأداء سلس وسريع حتى بالأجهزة المتوسطة.

للمستخدم العربي، تمبل رن 2 تجربة مثالية للترفيه السريع في الانتظار أو في الطريق. لا تحتاج إنترنت، لا تحتاج تسجيلاً، فقط افتح وابدأ الجري.

التحديثات الأخيرة شملت خرائط جديدة وشخصيات موسمية وتحسينات على التوافق مع أجهزة الأندرويد الحديثة.',
  '["Endless Running على خرائط بصرية مبهجة", "تحكم بالإمالة لممرات منحنية", "مقاطع Minecart متنوعة", "شخصيات متعددة بقدرات مختلفة", "تطوير قدرات بالعملات المجموعة", "مجانية كلياً بدون ضغط للدفع"]', '["خفيفة جداً 110 ميغابايت تعمل على الأجهزة القديمة", "لا تحتاج إنترنت بعد التنزيل", "مجانية بالكامل للاستمتاع الأساسي", "تحكم بالإمالة مميز وممتع"]', '["أقل تجديداً في المحتوى مقارنة بسابواي سيرف", "قدرات الشخصيات محدودة التنوع"]',
  '["حمّل تمبل رن 2 من متجر جوجل بلاي مجاناً", "افتحه وابدأ اللعب فوراً بدون إعداد", "اجمع عملات وارقَّ في القائمة", "اجمع الرموز الفضية الخاصة لفتح شخصيات جديدة"]', '[{"q": "هل تمبل رن 2 تعمل بدون إنترنت؟", "a": "نعم، تعمل بشكل كامل offline بعد التنزيل الأول بدون حاجة لأي اتصال."}, {"q": "كيف أحصل على عملات أسرع؟", "a": "استخدم قدرة المغناطيس عند توفرها، وجمع العملات المضاعفة، وأكمل المهام اليومية."}, {"q": "ما الفرق بين تمبل رن 1 و2؟", "a": "الجزء الثاني يتميز بجرافيكس أفضل وبيئات أكثر تنوعاً ومقاطع الميناكارت والتحكم بالإمالة المحسّن."}, {"q": "هل يمكن التنافس مع الأصدقاء؟", "a": "يمكن ربط اللعبة بجوجل للاطلاع على Leaderboard ومقارنة نتيجتك مع الأصدقاء."}]', 'آخر تحديثات تمبل رن 2 شملت خريطة Forest Adventure الجديدة وشخصية جديدة وتحسينات على التوافق مع الأجهزة الحديثة.',
  'تحميل تمبل رن 2 APK 2026 للأندرويد | Temple Run 2', 'حمّل تمبل رن 2 آخر إصدار APK 2026 للأندرويد مجاناً والعب الأكثر إثارة منألعاب الجري اللامتناهي.', 'تحميل تمبل رن 2, Temple Run 2 APK, تمبل رن للأندرويد, تنزيل Temple Run, تمبل رن 2026, تحميل تمبل رن مجاناً',
  4.8, 51050, 65133, 'published', 'مجاني',
  NOW() - INTERVAL 19 DAY, NOW() - INTERVAL 5 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'أمازون شوبينج', 'amazwn-shwbynj', (SELECT id FROM categories WHERE slug='apps' LIMIT 1), 'Amazon Mobile LLC', 'com.amazon.mShop.android.shopping', 'https://play.google.com/store/apps/details?id=com.amazon.mShop.android.shopping',
  'أمازون شوبينج هو السوق العالمي في جيبك، مئات الملايين من المنتجات بضغطة واحدة وتوصيل سريع.', 'لو بدك تشتري أي شيء في العالم وأنت جالس في بيتك، أمازون هو الاسم الأول الذي يتبادر للذهن. من سنة 1994 حين بدأها جيف بيزوس كمتجر كتب صغير عبر الإنترنت، صارت أمازون اليوم أكبر متجر إلكتروني في العالم بمئات الملايين من المنتجات وخدمات لوجستية لا مثيل لها.

أمازون شوبينج من تطوير Amazon Mobile LLC وهو التطبيق الرسمي لمتجر أمازون على الأندرويد. التطبيق مجاني للتنزيل والاستخدام والشراء يتم بطرق دفع متعددة آمنة. للمنطقة العربية، أمازون يخدم الإمارات والسعودية ومصر ودولاً عربية أخرى بشكل مباشر.

محرك البحث الذكي بأمازون يعطيك نتائج مخصصة بناءً على تاريخ بحثك وشرائك. بتكتب ما تريد وبتلاقي آلاف النتائج مرتبة حسب الصلة والسعر والتقييم. الفلاتر المتقدمة بتخليك تضيق النتائج بسرعة لتحصل على ما تريد بدون تصفح لا نهاية له.

تقييمات المستخدمين هي من أقوى نقاط قوة أمازون. كل منتج عنده آراء حقيقية من مشترين سابقين مع صور وتفاصيل دقيقة. هيك التقييمات تساعدك على اتخاذ قرار شراء مستنير بدون أن تضطر لتجربة المنتج شخصياً. أمازون صارمة في مكافحة التقييمات المزورة مما يجعل نظامها من الأكثر موثوقية.

برنامج Prime هو العرض الأكبر من أمازون. بسعر اشتراك سنوي معقول بتحصل على شحن مجاني أسرع على ملايين المنتجات، وصول لـ Prime Video لمشاهدة الأفلام والمسلسلات، Prime Music وغيرها. للمتسوقين المتكررين Prime يوفر كثيراً من رسوم الشحن خلال العام.

أمازون Alexa Shopping القائمة الصوتية تتيح إضافة منتجات لسلة التسوق بالصوت لو أنت مستخدم Alexa. وفي داخل التطبيق يمكن البحث بالصورة، بتصوّر أي منتج أمامك ويبحث عنه التطبيق تلقائياً.

تتبع الطلبات Real-Time ممتاز. بعد الشراء بتقدر تتابع رحلة طرودك من المستودع لباب بيتك خطوة بخطوة مع إشعارات في كل مرحلة. شركات الشحن الشريكة مع أمازون تتيح تتبعاً دقيقاً جداً.

المنتجات العربية بأمازون صارت أفضل بكثير مقارنة بسنوات سابقة. amazon.ae وamazon.sa يوفران مخزوناً ضخماً يخدم المنطقة، وكتير منتجات صارت تُشحن من مستودعات محلية مما يختصر وقت التوصيل كثيراً.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 110 ميغابايت. الأداء سلس وسريع مع تحميل صور المنتجات بجودة عالية. الواجهة مريحة للاستخدام اليومي.

التحديثات الأخيرة شملت تحسينات على تجربة البحث، وإضافة خاصية المقارنة المباشرة بين المنتجات، وتحسينات على التتبع الحي للطلبات.',
  '["مئات الملايين من المنتجات بأسعار تنافسية", "بحث بالصورة لإيجاد المنتجات", "تقييمات موثوقة من مشترين حقيقيين", "تتبع طلبات حي خطوة بخطوة", "برنامج Prime بمزايا شاملة", "طرق دفع متعددة وآمنة"]', '["أوسع تشكيلة منتجات على الإطلاق", "تقييمات موثوقة تساعد على الشراء الصح", "خدمة عملاء ممتازة وسياسة إرجاع سهلة", "توصيل سريع مع برنامج Prime"]', '["المنتجات العربية أقل من المتاح للدول الغربية", "بعض المنتجات من بائعين ثانويين قد تكون جودتها متفاوتة"]',
  '["حمّل أمازون شوبينج من متجر جوجل بلاي", "أنشئ حساباً أو سجّل دخولك", "أضف عنوان التوصيل وطريقة الدفع", "ابدأ التسوق وتتبع طلباتك"]', '[{"q": "هل أمازون متاح في كل الدول العربية؟", "a": "أمازون متاح مباشرة في الإمارات والسعودية ومصر. لدول أخرى يمكن الطلب عبر التحويل الدولي مع تكاليف شحن إضافية."}, {"q": "هل الشراء من أمازون آمن؟", "a": "نعم، أمازون تستخدم تشفير SSL وبوابات دفع آمنة، وفيها سياسة حماية الشراء وإرجاع المنتجات."}, {"q": "كيف أرجع منتجاً اشتريته؟", "a": "من قسم الطلبات في حسابك اختر الطلب ثم Return or Replace Items واتبع التعليمات."}, {"q": "هل يستحق اشتراك Prime؟", "a": "لو بتتسوق من أمازون أكثر من مرتين شهرياً، Prime يوفر رسوم الشحن بسرعة ويعطيك مزايا إضافية كثيرة."}]', 'آخر تحديثات أمازون شوبينج شملت تحسينات على تجربة البحث بالصورة والصوت، وواجهة محسّنة لعرض المنتجات، وتحسينات على متابعة الطلبات بالخريطة.',
  'تحميل أمازون شوبينج APK 2026 للأندرويد | Amazon Shopping', 'حمّل أمازون شوبينج آخر إصدار APK 2026 للأندرويد وتسوق من ملايين المنتجات بتوصيل سريع وآمن.', 'تحميل أمازون, Amazon Shopping APK, أمازون للأندرويد, تنزيل أمازون, Amazon 2026, تحميل أمازون مجاناً, تسوق أمازون',
  4.8, 26375, 193978, 'published', 'مجاني',
  NOW() - INTERVAL 36 DAY, NOW() - INTERVAL 17 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'علي إكسبريس', 'aly-iksbrys', (SELECT id FROM categories WHERE slug='apps' LIMIT 1), 'Alibaba Mobile', 'com.alibaba.aliexpresshd', 'https://play.google.com/store/apps/details?id=com.alibaba.aliexpresshd',
  'علي إكسبريس هو جنة الأسعار الرخيصة، أي شيء تتخيله موجود هنا بسعر يفاجئك.', 'كتير ناس اكتشفوا علي إكسبريس بالصدفة، لما بحثوا عن منتج وضربوا على الرابط ليلاقوا نفس المنتج بسعر أقل بكتير مما اعتادوا عليه. من إكسسوارات الموبايل للملابس والأدوات والإلكترونيات، علي إكسبريس يقدم تشكيلة هائلة بأسعار يصعب منافستها في أي مكان آخر.

علي إكسبريس من تطوير Alibaba Mobile، ذراع المستهلكين الدولية لمجموعة Alibaba الصينية العملاقة. المنصة تربط بائعين صينيين صغاراً وكباراً مباشرة بمشترين حول العالم، مما يلغي كثيراً من الوسطاء ويخفض الأسعار.

البحث بالصورة هو من أقوى أدوات علي إكسبريس. بتصوّر أي شيء أمامك أو ترفع صورة من الإنترنت والتطبيق يبحث عن نفس المنتج أو ما يشبهه. هيك تجد أشياء لم تكن تعرف حتى اسمها الصحيح بالإنجليزية أو العربية.

تقييمات المشترين مصحوبة بصور حقيقية من لاعبين مستقلين في جميع أنحاء العالم. هيك التقييمات الصريحة تعطيك فكرة واقعية عن جودة المنتج قبل الشراء. بعض البائعين يطلبون من المشترين نشر تقييمات مقابل مكافآت، لذا انتبه دائماً لعدد التقييمات وتنوعها.

نظام الكوبونات والتخفيضات بعلي إكسبريس يعمل طوال السنة وبشكل مكثف خلال مواسم العروض مثل 11.11 وعيد الميلاد. بتقدر توفر مبالغ إضافية فوق الأسعار المنخفضة أصلاً. استخدام كوبونات متجر البائع مع الخصم العام يضاعف التوفير.

الشحن المجاني هو من أكثر ما يجذب لعلي إكسبريس. معظم المنتجات تُشحن مجاناً وإن كان الشحن المجاني يستغرق وقتاً أطول، 2-4 أسابيع في الغالب. لو بدك أسرع فيه خيارات شحن مدفوعة أسرع.

علي إكسبريس تطور كثيراً من ناحية وقت التوصيل للمنطقة العربية. أصبح لديهم مستودعات في بعض الدول العربية تتيح توصيلاً خلال أيام لبعض المنتجات، وهيك تحسّن التجربة للمشترين العرب بشكل ملحوظ.

الحماية من التلاعب قوية نسبياً. لو ما وصل المنتج أو كان مختلفاً كلياً عن الوصف، فيه Buyer Protection تسمح باسترداد كامل للمبلغ خلال مدة محددة. هيك الحماية تريّح المشترين من مخاوف الشراء عن بعد.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 160 ميغابايت. الأداء ممتاز وتحميل المنتجات سريع مع صور عالية الجودة. التطبيق يدعم العربية بشكل جيد في الواجهة.

التحديثات الأخيرة شملت تحسينات على البحث بالصورة، وميزة AR لتجربة المنتجات افتراضياً، وتوسيع شبكة التوصيل السريع للمنطقة العربية.',
  '["ملايين المنتجات بأسعار تنافسية مباشرة من الصين", "بحث بالصورة لإيجاد المنتجات بسهولة", "Buyer Protection لحماية مشترياتك", "كوبونات وعروض موسمية دائمة", "شحن مجاني لمعظم الدول", "تقييمات حقيقية بصور من المشترين"]', '["أخفض أسعار للمنتجات الصينية مباشرة", "تشكيلة هائلة تشمل كل فئة ممكنة", "Buyer Protection تضمن حقك", "بحث بالصورة ممتاز"]', '["الشحن المجاني بطيء قد يستغرق أسابيع", "جودة بعض المنتجات غير متوقعة، اقرأ التقييمات دائماً"]',
  '["حمّل علي إكسبريس من متجر جوجل بلاي", "أنشئ حساباً بإيميلك", "أضف عنوان التوصيل", "ابدأ التسوق وابحث بالصورة أو النص"]', '[{"q": "كم يستغرق التوصيل من علي إكسبريس؟", "a": "الشحن المجاني يستغرق عادة 2-6 أسابيع. الشحن المدفوع المسرّع AliExpress Standard يصل خلال 7-15 يوم."}, {"q": "هل الدفع بطاقة بنكية آمن؟", "a": "نعم، المدفوعات تمر عبر نظام Alipay الآمن وعندك Buyer Protection لحماية كاملة."}, {"q": "كيف أعرف إن البائع موثوق؟", "a": "انظر لتقييم البائع وعدد الطلبات المكتملة وتقييمات المنتج المصحوبة بصور حقيقية من مشترين."}, {"q": "كيف أسترد أموالي لو المنتج ما وصل؟", "a": "افتح نزاع Dispute خلال مدة Buyer Protection من صفحة الطلب وأرفق الأدلة وستسترد أموالك."}]', 'آخر تحديثات علي إكسبريس شملت تحسينات على البحث الذكي بالصورة، وتوسيع AliExpress Choice للشحن السريع، وواجهة تسوق محسّنة.',
  'تحميل علي إكسبريس APK 2026 للأندرويد | AliExpress تسوق', 'حمّل علي إكسبريس آخر إصدار APK 2026 للأندرويد وتسوق من ملايين المنتجات بأسعار منخفضة مع شحن مجاني.', 'تحميل علي إكسبريس, AliExpress APK, علي اكسبريس للأندرويد, تنزيل AliExpress, علي إكسبريس 2026, تسوق صيني, AliExpress مجاناً',
  4.1, 67826, 414626, 'published', 'مجاني',
  NOW() - INTERVAL 134 DAY, NOW() - INTERVAL 9 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'شيين', 'shyyn', (SELECT id FROM categories WHERE slug='apps' LIMIT 1), 'SHEIN Group', 'com.zzkko', 'https://play.google.com/store/apps/details?id=com.zzkko',
  'شيين هو مول الأزياء في هاتفك، موضة عصرية بأسعار لا تصدق ومجموعات جديدة كل يوم.', 'إذا كنت تحب الموضة وتريد تحديث خزانة ملابسك بدون إنفاق ثروة، شيين هو التطبيق الذي غيّر مفهوم التسوق للملابس بشكل جذري. من شركة صغيرة انطلقت في الصين سنة 2008، صار شيين اليوم واحداً من أسرع العلامات التجارية نمواً في العالم.

شيين من تطوير SHEIN Group وهي شركة Fast Fashion تعمل بنموذج مختلف: إنتاج كميات صغيرة من تصاميم كثيرة جداً بدل الكميات الضخمة من تصاميم محدودة. هيك يضمنون التنوع الهائل الذي يجذب الجمهور الواسع.

الكتالوج الهائل هو أبرز ميزة لشيين. آلاف القطع الجديدة تُضاف يومياً، من ملابس نسائية وذكورية وأطفال لأثاث البيت والإكسسوارات وكل شيء بينهما تقريباً. التصميمات متنوعة بين الكلاسيكي والعصري والكاجوال والرسمي.

الأسعار هي السلاح الأقوى لشيين. قميص بدولارين، فستان بعشرة دولارات، معطف بعشرين، هيك الأرقام التي جعلت الملايين يشترون بكميات لم يعتادوا عليها سابقاً. بالمقارنة مع محلات الملابس التقليدية الأسعار أقل بكثير.

نظام كوبونات وعروض شيين لا ينتهي. عروض يومية وأسبوعية وموسمية، وكوبونات ترحيب للمشترين الجدد، وبرامج ولاء للمشترين المتكررين. بتقدر دائماً تجد خصماً إضافياً فوق الأسعار المنخفضة أصلاً.

تقييمات المنتجات بصور حقيقية من المشترين تعطيك فكرة واقعية عن المقاسات والألوان. شيين تشجع المشترين على رفع صور وهم يرتدون المنتج، وهيك صار الكتالوج أكثر واقعية من مجرد صور استوديو مثالية.

سياسة الإرجاع معقولة لأول إرجاع مجاني. لو المقاس ما كان صحيحاً أو المنتج مختلف، بتقدر ترجعه خلال مدة محددة بسهولة. هيك تجربة التسوق تصبح أقل خطورة حتى لو ما تأكدت تماماً من المقاس.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 200 ميغابايت. الأداء ممتاز مع تحميل سريع للصور وتجربة تسوق سلسة. الواجهة باللغة العربية ودليل المقاسات يشمل مقارنة بالمقاسات العربية المعتادة.

المعارضة البيئية هي من أبرز انتقادات شيين. Fast Fashion يعني كميات هائلة من الملابس تُنتج وتُتخلص منها بسرعة، وهيك يخلق ضغطاً بيئياً كبيراً. وعي المستهلك بهيك تأثير مهم عند التسوق من شيين.

التحديثات الأخيرة شملت ميزة SHEIN LIVE للبث المباشر مع عروض حصرية، وتحسينات على دليل المقاسات الذكي، وتوسيع قسم المنزل والديكور.',
  '["آلاف التصاميم الجديدة يومياً", "أسعار تنافسية بأقل من السوق", "كوبونات وعروض موسمية دائمة", "تقييمات بصور حقيقية من المشترين", "دليل مقاسات دقيق ومقارن", "شحن لمعظم دول العالم"]', '["أخفض أسعار في سوق الأزياء", "تنوع هائل من التصاميم", "سياسة إرجاع مرنة", "عروض وخصومات لا تنتهي"]', '["تأثير بيئي سلبي لنموذج Fast Fashion", "الجودة غير متساوية بين المنتجات"]',
  '["حمّل شيين من متجر جوجل بلاي", "أنشئ حساباً وخذ كوبون الترحيب للمبتدئين", "أضف مقاساتك الصحيحة من دليل المقاسات", "ابدأ التسوق وأضف للعربة وادفع بأمان"]', '[{"q": "هل المقاسات في شيين دقيقة؟", "a": "غير متساوية دائماً. اقرأ تعليقات المشترين وخاصة من يذكرون المقاس، ودليل المقاسات بالسنتيمتر أدق."}, {"q": "كم يستغرق التوصيل من شيين؟", "a": "الشحن المجاني يستغرق 2-4 أسابيع عادة. الشحن المسرّع المدفوع يصل خلال 7-10 أيام."}, {"q": "هل يمكن الدفع بالكاش عند الاستلام؟", "a": "يتوفر في بعض الدول العربية كالإمارات والسعودية. تحقق من خيارات الدفع عند إتمام الطلب."}, {"q": "كيف أستفيد من كوبونات شيين؟", "a": "فعّل الإشعارات لتصلك العروض المؤقتة، وتحقق من قسم Coupons في حسابك، وأضف منتجات للمفضلة لتتابع انخفاض أسعارها."}]', 'آخر تحديثات شيين شملت إطلاق SHEIN LIVE للبث المباشر، وتحسينات على دليل المقاسات الذكي بالAI، وتوسيع تشكيلة المنزل والديكور.',
  'تحميل شيين APK 2026 للأندرويد | SHEIN تسوق أزياء', 'حمّل شيين آخر إصدار APK 2026 للأندرويد وتسوقي أحدث الأزياء بأسعار لا تصدق مع شحن لكل مكان.', 'تحميل شيين, SHEIN APK, شيين للأندرويد, تنزيل شيين, SHEIN 2026, ملابس شيين, تحميل SHEIN مجاناً',
  4.1, 79165, 352830, 'published', 'مجاني',
  NOW() - INTERVAL 168 DAY, NOW() - INTERVAL 5 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'تالابات', 'talabat', (SELECT id FROM categories WHERE slug='apps' LIMIT 1), 'Delivery Hero SE', 'com.talabat', 'https://play.google.com/store/apps/details?id=com.talabat',
  'تالابات هو مطبخ كل المطاعم الدنيا في شاشة موبايلك، وجبتك المفضلة على بابك خلال 30 دقيقة.', 'لما تجوع ولا بدك تطبخ ولا بدك تخرج، واحد من التطبيقات يلي بتلجأ له أكيد هو تالابات. منذ انطلاقها سنة 2004 كمنصة لتوصيل الطعام في الكويت، صارت تالابات اليوم المنصة الرائدة للتوصيل في الشرق الأوسط وشمال أفريقيا.

تالابات من تطوير Delivery Hero SE الشركة الألمانية يلي تمتلك أكبر شبكة توصيل طعام بالعالم. تالابات هي عملها الرئيسي بالمنطقة العربية، ونجحت في بناء ثقة ضخمة مع المطاعم والمستخدمين على حد سواء.

كتالوج المطاعم هو الجوهر. بتفتح التطبيق وبتكتب عنوانك ويظهرلك كل المطاعم التي توصل لمنطقتك. من أشهر سلاسل المطاعم العالمية للمطاعم المحلية الصغيرة، التشكيلة واسعة جداً وبتشمل كل المطابخ من عربي وشرقي وغربي وسريع وصحي.

تتبع الطلب الحي هو من أكثر ما يحبه المستخدمون. بمجرد تأكيد طلبك، بتقدر تتابع على خريطة حية رحلة طلبك من المطعم لبابك. مرحلة قبول المطعم، ثم التحضير، ثم التجميع، ثم انطلاق الدليفري، كل هيك بزمن حقيقي وخريطة مباشرة.

تالابات بقدمت ما هو أكثر من الطعام. تالابات Pro تتيح توصيل بقالة وصيدليات ومتاجر متنوعة بنفس سرعة الطعام. صار بإمكانك تطلب كيلو فراولة وعبوة مناديل وأدوية وكل هيك في نفس الطلب وبنفس الوقت.

برنامج الولاء talabat points يجمع نقاطاً مع كل طلب تستبدلها بخصومات لاحقة. فيه كمان عروض حصرية للمستخدمين المتكررين وكوبونات دورية. المستخدمون النشطون يوفرون جزءاً ملحوظاً من فاتورتهم الشهرية بهيك البرنامج.

الاشتراك talabat pro الشهري يتيح شحناً مجانياً غير محدود على الطلبات بقيمة معينة. لمن يطلب أكثر من 10 مرات شهرياً هيك الاشتراك مجدٍ اقتصادياً جداً مقارنة برسوم التوصيل المتراكمة.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 100 ميغابايت. الواجهة عربية وسهلة الاستخدام جداً وحتى كبار السن بيلاقون فيها سهولة.

تالابات تغطي الآن معظم الدول العربية الكبرى من الإمارات والسعودية والكويت والأردن ومصر وغيرها. التغطية داخل المدن ممتازة والأوقات الفعلية للتوصيل دقيقة نسبياً.

التحديثات الأخيرة شملت تحسينات على تتبع الطلب الحي، وتوسيع قسم Market للبقالة، وتحسينات على نظام التقييمات.',
  '["آلاف المطاعم والمتاجر بمنطقتك", "تتبع طلب حي على الخريطة", "توصيل بقالة وصيدلية وأكثر", "برنامج نقاط ولاء للمستخدمين", "تالابات Pro لشحن مجاني", "دفع بطرق متعددة تشمل الكاش"]', '["التغطية الأوسع للمطاعم بالمنطقة العربية", "تتبع دقيق وحي للطلب", "واجهة عربية سهلة", "يشمل توصيل بقالة ودواء"]', '["رسوم توصيل قد تكون مرتفعة بدون Pro", "توافر بعض المطاعم يختلف من منطقة لأخرى"]',
  '["حمّل تالابات من متجر جوجل بلاي", "أضف عنوانك للتوصيل", "تصفح المطاعم واختر ما يعجبك", "اطلب وتابع وجبتك حتى الباب"]', '[{"q": "هل يمكن الدفع نقداً عند الاستلام؟", "a": "نعم، معظم الدول التي يغطيها تالابات تدعم الدفع نقداً عند التسليم إلى جانب الدفع الإلكتروني."}, {"q": "كم يستغرق التوصيل؟", "a": "يعتمد على المطعم والمسافة، عادة 20-45 دقيقة. التوقع المبدئي يظهر قبل تأكيد الطلب."}, {"q": "هل يمكن إلغاء الطلب بعد تأكيده؟", "a": "يمكن الإلغاء خلال دقائق من التأكيد قبل أن يبدأ المطعم بالتحضير. بعد ذلك قد تكون هناك رسوم."}, {"q": "هل برنامج Pro يستحق الاشتراك؟", "a": "لو بتطلب 8 مرات أو أكثر شهرياً، Pro يوفر أكثر مما تدفعه من خلال توفير رسوم التوصيل."}]', 'آخر تحديثات تالابات شملت تحسينات جوهرية على خريطة تتبع الطلب، وتوسيع قسم Market، وتحسينات على سرعة التطبيق.',
  'تحميل تالابات APK 2026 للأندرويد | Talabat توصيل طعام', 'حمّل تالابات آخر إصدار APK 2026 للأندرويد واطلب من أفضل المطاعم مع تتبع حي وتوصيل سريع.', 'تحميل تالابات, Talabat APK, تالابات للأندرويد, تنزيل تالابات, توصيل طعام, Talabat 2026, تالابات مجاناً',
  4.2, 72257, 461166, 'published', 'مجاني',
  NOW() - INTERVAL 67 DAY, NOW() - INTERVAL 3 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'كريم', 'krym', (SELECT id FROM categories WHERE slug='apps' LIMIT 1), 'Careem Networks FZ LLC', 'com.careem.acma', 'https://play.google.com/store/apps/details?id=com.careem.acma',
  'كريم هو تطبيق التنقل العربي الأول، من التاكسي للدراجات للطعام والمدفوعات، كل شيء بتطبيق واحد.', 'لما تفكر بركوب أوبر في المنطقة العربية، كثيراً ما يخطر على بالك كريم بالمرتبة الأولى. والسبب بسيط: كريم ولد وترعرع بالمنطقة العربية وفهم احتياجاتها بشكل ما استطاع أي منافس غربي فهمه بنفس العمق.

كريم من تطوير Careem Networks FZ LLC وأسسه اثنان من المواطنين العرب في دبي سنة 2012. نجح في بناء امبراطورية خدمات تنقل وتوصيل في أكثر من 10 دول عربية قبل أن تستحوذ عليه أوبر في 2019 بمليار ومئتي مليون دولار. ورغم الاستحواذ بقي كريم يعمل تحت اسمه المستقل.

كريم الكار هو البداية والأشهر. تفتح التطبيق وتحدد نقطة انطلاقك ووجهتك، وفي دقيقة أو دقيقتين تنتظر سائق في طريقه إليك. السعر محدد مسبقاً لا مفاجآت، والدفع نقداً أو إلكترونياً. السائقون مقيّمون ومعروفة هوياتهم مما يعطي أمان أكبر من التاكسي التقليدي.

كريم Bus هو الخيار الاقتصادي في بعض المدن. وسيلة نقل مشترك برايس أقل من السيارة الخاصة لمن لا يعجله الأمر. هيك تخفض تكلفة التنقل بشكل ملحوظ مع الحفاظ على الراحة والأمان.

كريم فود للطعام يتنافس مع تالابات في بعض المدن. نفس مفهوم توصيل الطعام من مطاعم متعددة مع تتبع حي وخيارات دفع متعددة. استخدام كريم كريدت المتراكمة من ركوب السيارة يمكن استخدامه لطلب الطعام.

كريم باي هو محفظة إلكترونية متكاملة. بتشحن المحفظة وتستخدمها ليس فقط لكريم بل لمدفوعات أخرى متعددة في بعض الدول. هيك كريم تحول من تطبيق تنقل لمنصة خدمات متكاملة.

نقاط كريم مع كل ركوبة تتراكم وتستبدل بخصومات. الركاب المتكررون يوفرون مبالغ ملحوظة. فيه كمان باقات اشتراك شهرية توفر خصومات ثابتة.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج حوالي 130 ميغابايت. الواجهة العربية سهلة ودعم العملاء يعمل بالعربية في كل الدول التي يغطيها.

كريم يغطي الإمارات والسعودية ومصر والكويت والأردن وباكستان وغيرها. في كل مدينة يخدمها التغطية ممتازة والوقت الفعلي للوصول دقيق.

التحديثات الأخيرة شملت تطوير كريم باي، وتوسيع خدمات كريم فود، وتحسينات على خريطة التتبع الحي.',
  '["كريم كار للتنقل بسيارة خاصة", "كريم Bus للنقل الاقتصادي المشترك", "كريم فود لتوصيل الطعام", "كريم باي محفظة إلكترونية", "نقاط ولاء مع كل ركوبة", "تتبع حي لموقع السائق"]', '["الأكثر ثقة بالمنطقة العربية", "منصة خدمات متكاملة لا مجرد تاكسي", "دعم عملاء بالعربية", "طرق دفع متعددة تشمل النقد"]', '["الأسعار أعلى قليلاً من بدائل أخرى في بعض الأوقات", "الخدمات المتقدمة غير متاحة في كل المدن"]',
  '["حمّل كريم من متجر جوجل بلاي", "أدخل رقمك وأنشئ حساباً", "أضف طريقة الدفع المفضلة", "احجز ركوبتك الأولى وتتبع السائق"]', '[{"q": "هل كريم آمن؟", "a": "نعم، السائقون معروفون ومقيّمون وبياناتهم مسجلة. التطبيق يتيح مشاركة رحلتك مع الأصدقاء وزر طوارئ."}, {"q": "كيف أضمن وصول السائق في الوقت الصحيح؟", "a": "احجز مسبقاً لو عندك موعد محدد، وراقب موقع السائق الحي وتواصل معه مباشرة من التطبيق."}, {"q": "هل يمكن الدفع نقداً في كريم؟", "a": "نعم في معظم الدول التي يغطيها. اختر Cash عند الحجز وادفع للسائق عند الوصول."}, {"q": "هل كريم يعمل في سوريا؟", "a": "حالياً كريم متاح في دول محددة لا تشمل سوريا. لكن يمكن استخدامه عند السفر للدول التي يغطيها."}]', 'آخر تحديثات كريم شملت تطوير كريم باي، وتوسيع خدمات فود في مدن جديدة، وواجهة محسّنة بتصميم أكثر حداثة.',
  'تحميل كريم APK 2026 للأندرويد | Careem تاكسي وتوصيل', 'حمّل كريم آخر إصدار APK 2026 للأندرويد واحجز تاكسيك واطلب طعامك وادفع إلكترونياً بتطبيق واحد.', 'تحميل كريم, Careem APK, كريم للأندرويد, تنزيل كريم, Careem 2026, تاكسي كريم, تحميل كريم مجاناً',
  4.6, 47866, 93251, 'published', 'مجاني',
  NOW() - INTERVAL 314 DAY, NOW() - INTERVAL 20 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
