  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'نمشي', 'nmshy', (SELECT id FROM categories WHERE slug='apps' LIMIT 1), 'Namshi FZCO', 'com.namshi.android', 'https://play.google.com/store/apps/details?id=com.namshi.android',
  'نمشي هو الوجهة العربية الأولى للأزياء والأحذية من أفخر العلامات، بتوصيل يصل بابك في يومين.', 'عندما تبحث عن أزياء وأحذية ذات علامات تجارية أصلية مع توصيل سريع للمنطقة العربية، نمشي هو الجواب. منذ انطلاقه في دبي سنة 2011، صار نمشي أكثر منصة موثوقة للأزياء الراقية في منطقة الخليج والشرق الأوسط.

نمشي من تطوير Namshi FZCO وتمتلكه مجموعة Noon منذ 2017. التركيز الرئيسي على الأزياء والأحذية والإكسسوارات من علامات تجارية مشهورة عالمياً مثل Nike وAdidas وTommy Hilfiger وZARA وغيرها. المنتجات معظمها أصلية 100% وليست تقليداً.

الكتالوج يضم آلاف الماركات والمنتجات من أبرز العلامات العالمية والمحلية. من الملابس الرياضية لملابس المكتب للأزياء الكاجوال، تجد تشكيلة واسعة لكل المناسبات والأذواق. التحديث مستمر بوصول مجموعات جديدة من الموسم الجاري.

التوصيل السريع هو ما يميز نمشي عن كثير من المنافسين. معظم الطلبات داخل دول الخليج تصل خلال يوم واحد أو يومين كحد أقصى. هيك بتقدر تطلب اليوم وتستلم غداً بدون طول الانتظار المعتاد بالتسوق الإلكتروني الدولي.

الإرجاع المجاني هو سياسة واضحة في نمشي. لو المنتج ما عجبك أو المقاس غير مناسب، بتقدر ترجعه خلال 30 يوماً من الاستلام بدون رسوم إرجاع. هيك التجربة تصبح بلا مخاطرة وبتشتري بثقة أكبر.

عروض Sale الموسمية ضخمة بنمشي. تخفيضات النهاية الموسمية تصل أحياناً لـ 70% على ماركات أصيلة. الاشتراك بالإشعارات ضروري لما تعلن عن هيك الأحداث لأن الكميات تنتهي بسرعة.

تطبيق نمشي مصمم بشكل جميل يتيح عرض المنتجات بصور عالية الجودة من زوايا متعددة. المقارنة بين المنتجات سهلة وفلاتر البحث بالماركة والحجم واللون والسعر دقيقة وسريعة.

التطبيق متاح على أندرويد 8.0 وما فوق ويحتاج 80 ميغابايت فقط وهو خفيف نسبياً. الأداء ممتاز مع تحميل سريع للصور ومعالجة للطلبات.

نمشي يغطي الإمارات والسعودية والكويت والبحرين وقطر وعُمان ومصر والأردن. التغطية في هيك الدول ممتازة مع أوقات توصيل سريعة.

التحديثات الأخيرة شملت تحسينات على محرك البحث والتصفية، وتوسيع قسم الأطفال، وإضافة ميزة تجربة الإكسسوارات افتراضياً.',
  '["آلاف العلامات التجارية الأصيلة العالمية", "توصيل يوم أو يومين لدول الخليج", "إرجاع مجاني حتى 30 يوماً", "عروض موسمية بتخفيضات تصل 70%", "فلاتر بحث متقدمة بالماركة والمقاس واللون", "ضمان أصالة المنتجات 100%"]', '["ضمان أصالة المنتجات من ماركات عالمية", "توصيل سريع جداً لدول الخليج", "إرجاع مجاني بدون تعقيد", "تشكيلة واسعة من الأزياء الراقية"]', '["الأسعار أعلى من متاجر السوق غير الرسمي", "التغطية الجغرافية محدودة بمنطقة الخليج والشام"]',
  '["حمّل نمشي من متجر جوجل بلاي", "أنشئ حساباً وأضف بياناتك وعنوانك", "فلتر البحث بحسب المقاس والماركة", "اطلب وانتظر توصيلك السريع"]', '[{"q": "هل منتجات نمشي أصلية 100%؟", "a": "نعم، نمشي يتعامل مع موزعين رسميين معتمدين وضمان الأصالة هو أساس عملهم."}, {"q": "كيف أعرف المقاس الصحيح؟", "a": "كل منتج عنده دليل مقاسات مفصل، وتقييمات المشترين تشير عادة لهل المقاس كبير أو صغير عن المعتاد."}, {"q": "هل الشحن مجاني؟", "a": "الشحن مجاني للطلبات التي تتجاوز حداً معيناً يختلف بكل دولة. للطلبات الأصغر رسوم شحن معقولة."}, {"q": "هل يمكن الدفع نقداً في نمشي؟", "a": "نعم، الدفع عند الاستلام متاح في معظم الدول التي تغطيها مع رسوم رمزية في بعض الأحيان."}]', 'آخر تحديثات نمشي شملت تحسينات على محرك البحث الذكي، وتوسيع قسم Sport والإكسسوارات، وتجربة تجربة الإكسسوارات بـ AR.',
  'تحميل نمشي APK 2026 للأندرويد | Namshi أزياء ماركات', 'حمّل نمشي آخر إصدار APK 2026 للأندرويد وتسوق أزياء وأحذية من أصيلة من أشهر الماركات بتوصيل سريع.', 'تحميل نمشي, Namshi APK, نمشي للأندرويد, تنزيل نمشي, Namshi 2026, تسوق ماركات, نمشي مجاناً',
  4.4, 76872, 566396, 'published', 'مجاني',
  NOW() - INTERVAL 229 DAY, NOW() - INTERVAL 28 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'نورد VPN', 'nwrd-vpn', (SELECT id FROM categories WHERE slug='tools' LIMIT 1), 'Nord Security', 'com.nordvpn.android', 'https://play.google.com/store/apps/details?id=com.nordvpn.android',
  'شبكة VPN آمنة وسريعة تحمي خصوصيتك وتتجاوز القيود الجغرافية بضغطة واحدة.', 'نورد VPN هو واحد من أفضل تطبيقات الشبكات الافتراضية الخاصة في العالم، بيجمع بين الأمان العالي والسرعة الخرافية وسهولة الاستخدام بشكل ما في تطبيق ثاني. لو كنت تبحث عن طريقة تحمي فيها خصوصيتك على الإنترنت وتتجاوز القيود الجغرافية وتستخدم الواي فاي العام بدون خوف، هاد هو التطبيق اللي تحتاجه.

التطبيق بيعمل عن طريق تشفير كل البيانات اللي بتنتقل من وإلى جهازك، مما يعني إنه حتى لو حدا اعترض اتصالك، ما رح يقدر يقرأ شي. بيستخدم تشفير AES-256 العسكري اللي بعتبر من أقوى أنواع التشفير الموجودة حالياً، مع دعم بروتوكولات متعددة مثل NordLynx المبني على WireGuard وOpenVPN وIKEv2.

عندك إمكانية الوصول لأكثر من 6200 سيرفر موزعة في 111 دولة حول العالم، مما يعطيك حرية اختيار الموقع اللي تريده سواء كنت بدك تشوف محتوى أمريكي أو بريطاني أو ياباني أو غيره. السيرفرات متوزعة بذكاء لتعطيك أسرع اتصال ممكن بناءً على موقعك الحالي.

من أبرز الميزات اللي بتميز نورد عن المنافسين هي ميزة Double VPN اللي بتمرر اتصالك عبر سيرفرين بدل واحد لمضاعفة الحماية، وميزة Onion Over VPN للوصول لشبكة Tor عبر VPN لأقصى درجات الخصوصية. في كمان ميزة Meshnet اللي بتخليك تنشئ شبكة خاصة بينك وبين أجهزتك الأخرى أو أصدقائك.

ميزة Kill Switch هي من أهم الميزات اللي لازم تكون موجودة بأي VPN محترم، وهي عندنا طبعاً. بتقطع اتصالك بالإنترنت تلقائياً لو انقطع الـ VPN، مما يمنع تسرب بياناتك الحقيقية. في نسخة التطبيق للأندرويد بتقدر تفعّل أو تعطّل هاي الميزة حسب احتياجك.

بالنسبة للسرعة، نورد دايماً بيكون ضمن الأسرع في اختبارات المقارنة المستقلة. بفضل بروتوكول NordLynx المطور خصيصاً، بتقدر تحصل على سرعات قريبة من سرعة اتصالك الأصلية، مما يعني إنك تقدر تشوف فيديوهات 4K وتلعب ألعاب أونلاين وتحمّل ملفات كبيرة بدون تأثير ملحوظ.

فيه قسم مخصص للـ Threat Protection Lite جوا التطبيق بيحجب الإعلانات والروابط الضارة والمواقع المخترقة تلقائياً، مما يعطيك طبقة حماية إضافية حتى لما تكون متصل بالإنترنت عادي بدون VPN.

إدارة الحساب والاشتراكات سهلة جداً من التطبيق، وبتقدر تستخدم نفس الاشتراك على 6 أجهزة مختلفة في نفس الوقت. التطبيق بيدعم اللغة العربية وواجهته بسيطة جداً، بضغطة وحدة بتكون متصل بأقرب سيرفر تلقائياً أو بتختار السيرفر اللي تريده من القائمة.',
  '["أكثر من 6200 سيرفر في 111 دولة حول العالم", "تشفير AES-256 عسكري مع دعم NordLynx وOpenVPN وIKEv2", "ميزة Double VPN لمضاعفة الحماية عبر سيرفرين", "Kill Switch تلقائي يمنع تسرب البيانات عند انقطاع VPN", "Threat Protection Lite لحجب الإعلانات والمواقع الضارة", "يدعم 6 أجهزة في نفس الوقت باشتراك واحد"]', '["شبكة سيرفرات ضخمة وسريعة جداً", "أمان وخصوصية لا مثيل لهما", "واجهة بسيطة وسهلة الاستخدام", "ميزات متقدمة مثل Double VPN وMeshnet"]', '["الاشتراك المدفوع مطلوب للاستخدام الكامل", "النسخة المجانية محدودة جداً"]',
  '["حمّل التطبيق وافتحه وسجّل حساب جديد أو سجّل دخول", "اختر خطة الاشتراك المناسبة أو جرّب النسخة المجانية", "اضغط على زر الاتصال الكبير للاتصال بأقرب سيرفر تلقائياً", "أو اختر دولة محددة من قائمة السيرفرات حسب حاجتك"]', '[{"q": "هل نورد VPN آمن فعلاً؟", "a": "أيوه، نورد VPN من أكثر تطبيقات VPN أماناً وبتم مراجعته بشكل مستقل من شركات أمنية محترمة. بيستخدم تشفير AES-256 ولديه سياسة no-logs صارمة."}, {"q": "هل يبطئ الإنترنت كثيراً؟", "a": "مع بروتوكول NordLynx، فقدان السرعة يكون ضئيل جداً، كثير من المستخدمين ما بيلاحظوا فرق ملحوظ في السرعة."}, {"q": "هل يعمل مع Netflix والمواقع المحجوبة؟", "a": "أيوه، نورد معروف بقدرته على تجاوز قيود البث مثل Netflix الأمريكي وBBC iPlayer وغيرها."}]', 'تحسينات على سرعة الاتصال مع بروتوكول NordLynx، إضافة سيرفرات جديدة في مناطق آسيا، تحسين استقرار Kill Switch على أندرويد 14.',
  'تحميل نورد VPN للأندرويد - أسرع وأأمن VPN 2025', 'حمّل نورد VPN للأندرويد مجاناً. أكثر من 6200 سيرفر في 111 دولة، تشفير عسكري، حماية كاملة لخصوصيتك وتجاوز الحجب.', 'نورد VPN, تحميل VPN للأندرويد, VPN مجاني, تجاوز الحجب, حماية الخصوصية, شبكة افتراضية خاصة',
  4.2, 57984, 205513, 'published', 'مجاني',
  NOW() - INTERVAL 44 DAY, NOW() - INTERVAL 13 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'فايرفوكس', 'fayrfwks', (SELECT id FROM categories WHERE slug='tools' LIMIT 1), 'Mozilla', 'org.mozilla.firefox', 'https://play.google.com/store/apps/details?id=org.mozilla.firefox',
  'متصفح الويب الحر والمفتوح المصدر من Mozilla — سريع وآمن ويحترم خصوصيتك.', 'فايرفوكس هو المتصفح الأسطوري من Mozilla، المنظمة غير الربحية اللي آمنت بالإنترنت الحر والمفتوح قبل ما يكون هاد الحكي موضة. من أوائل المتصفحات اللي حاربت احتكار إنترنت إكسبلورر وغيّرت مشهد التصفح للأبد، وهلق لسه في أقدام السباق بميزات ما تلاقيها عند غيره.

الميزة الأساسية اللي بتميز فايرفوكس عن كروم وغيره هي الالتزام الجوهري بالخصوصية. بشكل افتراضي، فايرفوكس بيحجب المتعقبين والكوكيز من الطرف الثالث ويمنع بصمة المتصفح، بدون ما تضطر تعمل إعدادات معقدة. مؤسسة Mozilla ليس لديها نموذج عمل مبني على بيع بياناتك لأن المنظمة غير ربحية ومستقلة.

على الأندرويد، فايرفوكس بيدعم إضافات المتصفح الكاملة، وهاي ميزة نادرة في متصفحات الموبايل. بتقدر تركّب uBlock Origin لحجب الإعلانات، أو Bitwarden لإدارة كلمات المرور، أو أي إضافة ثانية من المكتبة الضخمة. هاد الشي وحده بيخلي فايرفوكس لا منافس له لناس بتعرف شو بتعمل.

واجهة التطبيق تم تصميمها خصيصاً للموبايل مع شريط العنوان في الأسفل للوصول السهل بإبهامك، وتصميم نظيف وبسيط ما فيه تشتيت. التبويبات بتنظم بشكل أفقي مريح، وفيه وضع التصفح الخاص اللي بيمسح كل شي تلقائياً ما بحفظ أي سجل.

مزامنة Firefox Sync بتخلّيك توصل لبياناتك من أي جهاز — كلمات المرور والإشارات المرجعية والتبويبات المفتوحة والتاريخ — بدون ما تحتاج تمرّ من غوغل أو أبل. الحساب مجاني وبتقدر تمسح بياناتك من سيرفرات Mozilla في أي وقت.

ميزة Firefox Relay مدمجة جزئياً في المتصفح لإخفاء بريدك الإلكتروني الحقيقي عند التسجيل في مواقع ما تثق فيها كثير. وميزة Firefox Monitor بتعلمك لو ظهر بريدك الإلكتروني في أي قاعدة بيانات مسرّبة.

أداء فايرفوكس تحسّن كثير في السنوات الأخيرة بعد إعادة كتابة محرك الرسومات. التطبيق بات سريع ويستهلك ذاكرة معقولة مقارنة بكروم اللي مشهور بأكل الرام. على الأجهزة القديمة أو المتوسطة، الفرق بيكون ملحوظ.

المصدر المفتوح لفايرفوكس يعني إن المجتمع بيفحص الكود باستمرار وبيكتشف المشاكل الأمنية بسرعة. كمان يعني إنك تقدر تعدّل التطبيق وتبني عليه إذا عندك المهارة، وهاد اللي أنتج متصفحات زي Fenix وIceCat وغيرها.',
  '["حجب المتعقبين والكوكيز من الطرف الثالث بشكل افتراضي", "دعم إضافات المتصفح الكاملة على الموبايل مثل uBlock Origin", "مزامنة Firefox Sync عبر جميع الأجهزة بشكل آمن", "شريط العنوان في الأسفل لاستخدام مريح بإبهامك", "وضع التصفح الخاص الكامل مع حذف تلقائي", "مفتوح المصدر وغير ربحي — بياناتك مش للبيع"]', '["أفضل احترام للخصوصية من بين المتصفحات الكبرى", "دعم إضافات الكمبيوتر على الموبايل — ميزة نادرة", "مجاني بالكامل بدون أي اشتراكات", "مفتوح المصدر وشفاف تماماً"]', '["أبطأ قليلاً من كروم في بعض المواقع الثقيلة", "بعض مواقع الشركات محسّنة لكروم فقط"]',
  '["حمّل التطبيق وافتحه، اختر فايرفوكس كمتصفح افتراضي من الإعدادات للراحة", "أنشئ حساب Firefox أو سجّل دخول لمزامنة بياناتك", "اذهب لقائمة الإضافات وركّب uBlock Origin لحجب الإعلانات", "فعّل التصفح المحسّن لمكافحة التتبع من إعدادات الخصوصية"]', '[{"q": "هل فايرفوكس أفضل من كروم للخصوصية؟", "a": "أيوه بكثير. فايرفوكس بيحجب المتعقبين بشكل افتراضي وما بجمع بياناتك لأغراض إعلانية، بعكس كروم اللي تابع لغوغل."}, {"q": "هل تشغيل الإضافات على الموبايل مثل الكمبيوتر؟", "a": "قريب جداً. فايرفوكس أندرويد بيدعم عشرات الإضافات بما فيها أهمها مثل uBlock Origin وBitwarden وDark Reader."}, {"q": "هل Firefox Sync آمن؟", "a": "أيوه، بياناتك مشفّرة end-to-end قبل ما تتزامن. Mozilla نفسها ما تقدر تقرأ بياناتك."}]', 'تحديث محرك جافاسكريبت لأداء أسرع، تحسينات على واجهة إدارة الإضافات، إصلاح مشاكل استقرار على بعض أجهزة أندرويد 14، دعم أفضل للمواقع العربية RTL.',
  'تحميل فايرفوكس للأندرويد - متصفح آمن ومحترم للخصوصية 2025', 'حمّل فايرفوكس للأندرويد مجاناً. متصفح مفتوح المصدر من Mozilla مع حجب إعلانات وحماية خصوصية ودعم إضافات.', 'فايرفوكس أندرويد, تحميل firefox, متصفح آمن, حجب إعلانات, خصوصية الإنترنت, Mozilla Firefox',
  4.5, 33428, 108311, 'published', 'مجاني',
  NOW() - INTERVAL 220 DAY, NOW() - INTERVAL 30 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'برايف براوزر', 'brayf-brawzr', (SELECT id FROM categories WHERE slug='tools' LIMIT 1), 'Brave Software', 'com.brave.browser', 'https://play.google.com/store/apps/details?id=com.brave.browser',
  'متصفح متشدد في حماية الخصوصية مع حجب إعلانات مدمج وسرعة فائقة.', 'برايف براوزر هو المتصفح اللي انطلق من فكرة بسيطة وجريئة: إيش لو بنيت متصفح بيحجب كل الإعلانات والمتعقبين بشكل افتراضي وبشكل صح؟ النتيجة كانت متصفح أسرع من المنافسين، أكثر اهتماماً بالخصوصية، وفيه نموذج إعلاني اختياري بيكافئك كمستخدم بدل ما يستغلك.

برايف مبني على Chromium، نفس الأساس اللي بُني عليه كروم، مما يعني إنه متوافق مع كل المواقع وبتقدر تستخدم إضافات كروم عليه. لكن Brave أزال كل الكود المتعلق بجمع البيانات وأضاف طبقات حماية ضخمة فوق هاد الأساس.

الـ Brave Shields هي حاجب الإعلانات المدمج، وهو من أقوى وأسرع حجابات الإعلانات الموجودة. ما بيحتاج إضافات إضافية، كل شي مدمج في المتصفح ويعمل من اللحظة الأولى. المواقع بتتحمل أسرع بكثير لأن ملفات الإعلانات والمتعقبين الثقيلة بتتحجب قبل حتى ما تبدأ بالتحميل.

برايف بيقدم إحصائيات مفصلة بكم إعلان وكم متتبع حجبهم، وكم وقت وبيانات وفّر عليك. الأرقام بتبان جلية: عادةً بتوفر 30-70% من بيانات التصفح ووقت التحميل.

نموذج Brave Rewards هو الفكرة الأكثر إبداعاً. بتقدر تختار تشوف إعلانات احترامية (من شركات الإعلان التابعة لـ Brave) وتكسب عملة BAT مقابل وقتك، أو تتبرع بهاي العملة للمواقع اللي تحبها. هاد نموذج الإعلان المحترم — بدل ما شركات إعلانات تكسب على حسابك بدون ما تعرف.

برايف Search متاح كمحرك بحث افتراضي اختياري، وهو محرك بحث مستقل ما بيعتمد على جوجل أو بينغ ونتائجه من فهرسه الخاص. أو تقدر تختار DuckDuckGo أو محرك ثاني يحترم خصوصيتك.

Tor integration في برايف يعني إنك بضغطة تفتح نافذة تتصفح فيها عبر شبكة Tor بدون ما تحتاج تطبيق منفصل. هاد للمستخدمين اللي يحتاجون أقصى درجات الخصوصية.

المتصفح بيدعم أيضاً كلمات المرور المدمجة، ومزامنة Brave Sync لمزامنة بياناتك بين الأجهزة بشكل مشفر من طرف لطرف. الكود مفتوح المصدر ومتاح للفحص على GitHub.

على الأندرويد، واجهة برايف نظيفة وسريعة، وبتشغّل محتوى يوتيوب والمواقع بسرعة ملحوظة مقارنة بكروم. استهلاك البطارية أقل أيضاً بسبب حجب الكود الإعلاني الثقيل.',
  '["Brave Shields: حجب إعلانات ومتعقبين مدمج وشديد الفاعلية", "إحصائيات مفصلة عن الإعلانات المحجوبة والوقت الموفّر", "Brave Rewards: كسب عملة BAT مقابل مشاهدة إعلانات اختيارية", "تصفح Tor مدمج لأقصى درجات الخصوصية", "مزامنة Brave Sync المشفرة end-to-end", "مبني على Chromium — متوافق مع كل المواقع وإضافات كروم"]', '["أسرع متصفح للتصفح اليومي بفضل حجب الإعلانات", "خصوصية قوية جداً بدون إعدادات معقدة", "مجاني تماماً ومفتوح المصدر", "نموذج إعلاني مبتكر يكافئ المستخدم"]', '["بعض مواقع الأخبار قد تطلب تعطيل الحاجب", "Brave Rewards غير متاح في كل الدول"]',
  '["حمّل التطبيق وافتحه، بيطلب منك تعيينه متصفح افتراضي — وافق", "راجع إعدادات Brave Shields وتأكد إنها مفعّلة", "اختياري: فعّل Brave Rewards إذا بدك تكسب BAT", "أضف محرك بحث برايف أو DuckDuckGo من الإعدادات"]', '[{"q": "هل برايف أسرع من كروم؟", "a": "أيوه في معظم الأحوال، خصوصاً على المواقع اللي فيها كثير إعلانات. حجب الإعلانات بيخفّف الحمل على المتصفح والإنترنت."}, {"q": "ما هو BAT وكيف أستخدمه؟", "a": "BAT هو Basic Attention Token، عملة رقمية تكسبها مقابل مشاهدة إعلانات Brave الاختيارية. تقدر تتبرع بها للمواقع أو تحوّلها لمحفظتك."}, {"q": "هل يدعم إضافات كروم؟", "a": "على الكمبيوتر أيوه، لكن على الأندرويد الدعم محدود. بتقدر تضيف بعض الإضافات من متجر Brave."}]', 'تحسينات كبيرة على أداء Brave Shields في حجب الإعلانات الجديدة، تحديث محرك Chromium للنسخة الأخيرة، تحسين استهلاك الذاكرة على الأجهزة ذات الرام المنخفض، تحديثات أمنية مهمة.',
  'تحميل برايف براوزر للأندرويد - أسرع متصفح مع حجب إعلانات', 'حمّل برايف براوزر للأندرويد مجاناً. أسرع متصفح مع حجب إعلانات مدمج وحماية قوية للخصوصية ودعم Tor.', 'برايف براوزر, Brave Browser أندرويد, متصفح حجب إعلانات, خصوصية, BAT, متصفح سريع',
  4.7, 33595, 250020, 'published', 'مجاني',
  NOW() - INTERVAL 83 DAY, NOW() - INTERVAL 11 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'جيميل', 'jymyl', (SELECT id FROM categories WHERE slug='productivity' LIMIT 1), 'Google LLC', 'com.google.android.gm', 'https://play.google.com/store/apps/details?id=com.google.android.gm',
  'تطبيق البريد الإلكتروني الأكثر استخداماً في العالم من غوغل — سريع وذكي ومنظم.', 'جيميل هو تطبيق البريد الإلكتروني من غوغل، واللي غنّي عن التعريف. منذ إطلاقه عام 2004 وهو بيغير معايير البريد الإلكتروني، وعلى الأندرويد التطبيق بيقدم تجربة متكاملة وذكية بتعلمك إياها مرة وما بتحتاج غيره.

الميزة الأبرز في جيميل هي Intelligent Smart Reply والذكاء الاصطناعي المدمج. جيميل بيقترح ردوداً ذكية على الرسائل بناءً على محتواها، وبيقدر يكمّل الجمل اللي بتكتبها تلقائياً بميزة Smart Compose. هاد بيوفر وقت كبير خصوصاً للردود الروتينية.

التصنيف التلقائي للبريد الوارد هو من أقوى ميزات جيميل. الرسائل بتنقسم تلقائياً لتبويبات: الرئيسية، التواصل الاجتماعي، العروض، التحديثات، والمنتديات. هاد يعني إنك بتشوف الرسائل الشخصية المهمة أولاً دون ما تضيع وسط إعلانات المتاجر والتحديثات التلقائية.

واجهة جيميل على الأندرويد مصممة بشكل يناسب استخدام الموبايل تماماً. التنقل بالأرشفة بسحبة يمين، والحذف بسحبة يسار، والتبديل بين الحسابات بضغطة على الصورة الشخصية. كل شي سلس وبديهي.

البحث في جيميل من أقوى ميزاته — بتقدر تبحث عن رسالة من سنوات بكلمة واحدة وبتلاقيها فوراً. البحث بيدعم فلاتر متقدمة مثل from:، to:، subject:، has:attachment، لتحديد نتائجك بدقة.

جيميل بيدعم إضافة أكثر من حساب في نفس التطبيق — سواء حسابات Gmail أو حسابات Microsoft Outlook أو Yahoo أو أي IMAP/POP3. كل الحسابات بتدير من مكان واحد، ما بتحتاج تطبيق بريد منفصل لكل حساب.

من أهم الميزات للأعمال: يدعم Google Workspace الكامل، فبتقدر تفتح مستندات Drive مرفقة مباشرة، وتحدد مواعيد في تقويم غوغل من جوا الرسالة، وتنضم لمكالمات Meet. البيئة منسجمة.

التطبيق بيشتغل حتى بدون إنترنت لقراءة الرسائل المخزنة محلياً وكتابة ردود تتزامن لما يرجع الاتصال. وميزة الإرسال المؤجل بتخليك تكتب الرسالة هلق وتحدد وقت إرسالها لاحقاً.',
  '["Smart Reply وSmart Compose بالذكاء الاصطناعي لتوفير الوقت", "تصنيف تلقائي ذكي للبريد لتبويبات: رئيسية، اجتماعي، عروض", "بحث متقدم وسريع في كل تاريخ بريدك", "دعم حسابات متعددة Gmail وOutlook وYahoo وIMAP", "تكامل كامل مع Drive وCalendar وMeet وغيرها", "عمل بدون إنترنت وإرسال مؤجل للرسائل"]', '["الأذكى والأكثر موثوقية بين تطبيقات البريد", "مساحة تخزين 15GB مجاناً", "تكامل ممتاز مع منظومة غوغل", "أمان قوي وحماية من البريد المزعج"]', '["يتطلب حساب غوغل للاستخدام الأمثل", "الإعلانات تظهر في تبويب العروض"]',
  '["التطبيق مثبّت مسبقاً على معظم أجهزة أندرويد، أو حمّله من المتجر", "افتحه وسجّل دخول بحساب غوغل أو أضف حساب آخر", "فعّل إشعارات البريد المهمة فقط لتقليل التشتيت", "اضبط التبويبات حسب احتياجك من إعدادات البريد الوارد"]', '[{"q": "هل جيميل بيدعم حسابات Outlook وYahoo؟", "a": "أيوه، بتقدر تضيف أي حساب بريد إلكتروني يدعم IMAP أو POP3، بما فيها Outlook وYahoo وغيرها."}, {"q": "كم مساحة التخزين المجانية؟", "a": "15 غيغابايت مجاناً مشتركة مع Google Drive وPhotos. بتقدر ترقّي للمزيد بـ Google One."}, {"q": "كيف أرتّب البريد المزعج؟", "a": "جيميل بيرشّح البريد المزعج تلقائياً بدقة عالية. أي رسالة تنفذ ترشيحه، اضغط عليها واختر \'إبلاغ عن رسائل غير مرغوب فيها\'."}]', 'تحسينات على Smart Compose بالعربي، تحديثات أمنية لحماية الحساب، تحسين أداء التطبيق على الأجهزة القديمة، واجهة جديدة لعرض المرفقات.',
  'تحميل جيميل Gmail للأندرويد - تطبيق البريد الإلكتروني من', 'حمّل جيميل Gmail للأندرويد مجاناً. أذكى تطبيق بريد إلكتروني مع ذكاء اصطناعي وبحث متقدم وتكامل مع منظومة غوغل.', 'جيميل, Gmail أندرويد, تحميل gmail, بريد إلكتروني, Google Mail, ايميل',
  4.2, 21178, 92178, 'published', 'مجاني',
  NOW() - INTERVAL 142 DAY, NOW() - INTERVAL 20 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'مايكروسوفت أوتلوك', 'maykrwswft-awtlwk', (SELECT id FROM categories WHERE slug='productivity' LIMIT 1), 'Microsoft Corporation', 'com.microsoft.office.outlook', 'https://play.google.com/store/apps/details?id=com.microsoft.office.outlook',
  'تطبيق البريد والتقويم الاحترافي من مايكروسوفت — مثالي للعمل وإدارة الوقت.', 'مايكروسوفت أوتلوك على الأندرويد هو أكثر من مجرد تطبيق بريد إلكتروني — هو مركز الإنتاجية الكامل للمحترفين والشركات. إذا كنت بتستخدم بيئة مايكروسوفت في عملك (Microsoft 365، Teams، SharePoint)، أوتلوك هو التطبيق الذي لا غنى عنه لإدارة يومك.

أوتلوك بيجمع البريد الإلكتروني والتقويم وجهات الاتصال وإدارة الملفات في تطبيق واحد متكامل. من شاشة واحدة بتقدر تشوف بريدك الوارد، مواعيدك القادمة، والملفات اللي شاركها معك زملاؤك.

ميزة Focused Inbox في أوتلوك تعمل بالذكاء الاصطناعي لتحديد الرسائل الأهم وعرضها في تبويب "مركّز"، بينما بيروح الباقي لتبويب "آخر". التطبيق بيتعلم من تصرفاتك بمرور الوقت ويحسّن تصنيفه.

التكامل مع Microsoft Teams مباشرة من أوتلوك، بمعنى إنك بتقدر تحوّل بريد إلكتروني لمحادثة Teams، أو تبدأ مكالمة فيديو Teams مباشرة، أو تشارك ملفات من SharePoint بدون ما تخرج من التطبيق. هاد مستوى التكامل ما بتلاقيه بتطبيق بريد ثاني.

إدارة التقويم في أوتلوك من أقوى الأشياء فيه. بتقدر تشوف تقويمك الشخصي وتقاويم الزملاء في نفس الوقت، تجدول اجتماعات وتشوف أوقات الفراغ عند المشاركين تلقائياً، وتضيف غرف اجتماعات وروابط Teams. كل المعلومات منظمة ومتاحة.

يدعم أوتلوك أنواع حسابات متعددة: Microsoft 365، Exchange، Gmail، Yahoo، IMAP. كل الحسابات في تطبيق واحد وبتقدر تتنقل بينها بسهولة. فيه كمان دعم ممتاز لحسابات iCloud لمن عندهم أجهزة Apple أيضاً.

التطبيق بيدعم الوضع Dark والمظاهر المختلفة، وواجهته محسّنة للشاشات الكبيرة والأجهزة القابلة للطي. الشاشة المنقسمة Split Screen مدعومة بشكل ممتاز لمن يحبون العمل بتطبيقين في آن واحد.

أمان أوتلوك على مستوى المؤسسات: بيدعم سياسات MDM وMAM لـ IT administrators، تشفير رسائل S/MIME، وصل شرطي Conditional Access مع Azure Active Directory. الشركات الكبرى تثق فيه لأسباب وجيهة.

التطبيق متاح بشكل مجاني لحسابات Microsoft الشخصية، وبعض الميزات المتقدمة تحتاج اشتراك Microsoft 365 المدفوع.',
  '["Focused Inbox ذكاء اصطناعي يحدد الرسائل الأهم تلقائياً", "تكامل مباشر مع Microsoft Teams وSharePoint وOneDrive", "تقويم متقدم مع جدولة اجتماعات وعرض أوقات فراغ الزملاء", "دعم حسابات متعددة: Microsoft 365 وGmail وYahoo وExchange", "أمان مستوى المؤسسات مع دعم MDM وS/MIME", "وضع Split Screen وتصميم محسّن للشاشات الكبيرة"]', '["التكامل الأفضل في السوق مع منظومة مايكروسوفت", "إدارة تقويم قوية جداً مناسبة للشركات", "يدعم أكثر أنواع الحسابات تنوعاً", "أمان على مستوى المؤسسات"]', '["حجمه كبير (290 ميغابايت) مقارنة بتطبيقات البريد الأخرى", "الميزات الكاملة تحتاج اشتراك Microsoft 365"]',
  '["حمّل التطبيق وافتحه، اختر \'إضافة حساب\'", "سجّل دخول بحساب Microsoft أو أضف Gmail أو Outlook.com", "فعّل مزامنة التقويم وجهات الاتصال للاستفادة الكاملة", "اضبط Focused Inbox وقواعد التصنيف حسب احتياجك"]', '[{"q": "هل أوتلوك مجاني؟", "a": "التطبيق مجاني للتنزيل وللاستخدام الأساسي مع حسابات Microsoft الشخصية. بعض الميزات المتقدمة للمؤسسات تحتاج Microsoft 365."}, {"q": "هل يعمل مع Gmail؟", "a": "أيوه، بتقدر تضيف حساب Gmail في أوتلوك وتديره من نفس التطبيق مع كل حساباتك الأخرى."}, {"q": "كيف أشارك تقويمي مع زملاء العمل؟", "a": "من تقويم أوتلوك، اختر التقويم واضغط على \'مشاركة\'. بتقدر تحدد من يشوف ومستوى الوصول (قراءة فقط أو تعديل)."}]', 'تحسينات على تكامل Microsoft Copilot داخل البريد، تحديث واجهة التقويم بتصميم أنظف، تحسين أداء البحث وسرعة مزامنة Exchange، دعم أفضل لأجهزة أندرويد القابلة للطي.',
  'تحميل مايكروسوفت أوتلوك للأندرويد - تطبيق البريد الاحترافي', 'حمّل مايكروسوفت أوتلوك للأندرويد مجاناً. تطبيق بريد وتقويم احترافي مع تكامل Teams وOneDrive ومناسب للشركات.', 'مايكروسوفت أوتلوك, Outlook أندرويد, تحميل outlook, بريد العمل, Microsoft 365, ايميل مؤسسي',
  4.7, 51808, 124975, 'published', 'مجاني',
  NOW() - INTERVAL 308 DAY, NOW() - INTERVAL 8 DAY
);

INSERT IGNORE INTO apps (
  name, slug, category_id, developer, package_name, download_url,
  short_description, long_description, features, pros, cons,
  install_steps, faq, whats_new,
  seo_title, meta_description, keywords,
  rating, downloads, views, status, license,
  created_at, updated_at
) VALUES (
  'أنكي درويد', 'anky-drwyd', (SELECT id FROM categories WHERE slug='productivity' LIMIT 1), 'AnkiDroid Open Source Team', 'com.ichi2.anki', 'https://play.google.com/store/apps/details?id=com.ichi2.anki',
  'تطبيق البطاقات التعليمية الذكية المبني على علم الذاكرة — الأداة المثالية للحفظ الذكي.', 'أنكي درويد هو نسخة الأندرويد من Anki، التطبيق الأسطوري المبني على علم الذاكرة والتعلم الفعّال. إذا كنت طالب طب أو محامي بتحضّر امتحان أو شخص بده يتعلم لغة جديدة أو أي شي يحتاج حفظ، أنكي هو السلاح السري اللي بيستخدمه أفضل الطلاب حول العالم.

المبدأ الأساسي لأنكي هو Spaced Repetition — التكرار المتباعد. بدل ما تراجع كل شي كل يوم أو تحفظ قبل الامتحان بليلة وتنسى، أنكي بيعرضك للمعلومة قبل ما تنساها بوقت قصير. الخوارزمية بتحسب لكل بطاقة متى الوقت المثالي لمراجعتها بناءً على كم سهّلت أو صعّبت عليك بالمرة السابقة.

النتيجة: نسبة احتفاظ بالمعلومة تتجاوز 90% بجهد أقل بكثير من طرق الحفظ التقليدية. هاد مثبت علمياً وليس مجرد ادعاء.

أنكي درويد بيزامن مع Anki على الكمبيوتر عبر AnkiWeb المجاني، مما يعني إنك بتنشئ بطاقاتك على الكمبيوتر بنظافة وتراجعها على الموبايل في أي وقت — في الباص، بين المحاضرات، في أوقات الانتظار. كل دقيقة فاضية بتصير جلسة مراجعة مثمرة.

بتقدر تنشئ كل أنواع البطاقات: بطاقة الوجهين البسيطة (سؤال/جواب)، بطاقة Cloze (مع فراغات)، بطاقات بصور أو صوت. مش بس كلمات — بتقدر تتعلم نطق الكلمات بالصوت أو تحفظ الخرائط والمخططات بالصور.

أنكي مشهور خصوصاً بين طلاب الطب لأن في مكتبة ضخمة من الـ decks الجاهزة — مثل AnKing اللي بيغطي كل مادة USMLE. بتحمّل حزمة بطاقات جاهزة من مجتمع أنكي وتبدأ مراجعتك مباشرة بدون ما تضيع وقت بإنشاء البطاقات.

التطبيق مفتوح المصدر بالكامل ومجاني تماماً على الأندرويد (نسخة iOS مدفوعة لكن الأندرويد مجانية). لا إعلانات ولا اشتراكات ولا مزايا محجوبة. هاد جزء من الالتزام بالمصدر المفتوح.

إحصائيات أنكي مفصّلة تريك كم بطاقة راجعت يومياً، كم نسبة نجاحك، ومتى تنتهي من مراجعة كل deck. هاد يساعدك تخطط جدولك الدراسي بدقة وتعرف وين تركّز.

واجهة أنكي درويد أبسط من نسخة الكمبيوتر لكنها كاملة الوظائف. التصميم عملي بيركّز على سرعة الوصول لجلسات المراجعة. التطبيق خفيف جداً (30 ميغابايت) ويشتغل على أقدم الأجهزة.',
  '["خوارزمية Spaced Repetition علمية لأقصى كفاءة في الحفظ", "مزامنة مجانية مع Anki كمبيوتر عبر AnkiWeb", "دعم بطاقات نصية وصوتية ومصورة وCloze", "مكتبة ضخمة من الـ Decks الجاهزة للتحميل المجاني", "إحصائيات مفصلة لتتبع تقدمك وتخطيط المراجعة", "مفتوح المصدر ومجاني بالكامل بدون إعلانات"]', '["الأداة الأكثر فاعلية علمياً للحفظ طويل الأمد", "مجاني بالكامل مع مزامنة عبر الأجهزة", "مجتمع ضخم ومكتبة محتوى غنية", "خفيف جداً ويعمل على أقدم الأجهزة"]', '["منحنى تعلم في البداية لإعداد البطاقات والإعدادات", "الواجهة بسيطة جداً قد لا تروق للجميع"]',
  '["حمّل التطبيق وافتحه، أنشئ حساب AnkiWeb مجاني للمزامنة", "حمّل deck جاهزة من أنكيوب أو أنشئ بطاقاتك الخاصة", "ابدأ بجلسة مراجعة يومية من 10-20 دقيقة للحصول على أفضل نتائج", "عدّل إعدادات الـ deck (عدد البطاقات الجديدة يومياً) حسب وقتك"]', '[{"q": "ما الفرق بين أنكي درويد وQuizlet؟", "a": "أنكي يستخدم خوارزمية Spaced Repetition علمية أقوى بكثير من Quizlet، ومجاني بالكامل. Quizlet أسهل للمبتدئين لكن أنكي أفضل للتعلم الجدي."}, {"q": "هل أقدر أزامن مع أنكي على الكمبيوتر؟", "a": "أيوه، المزامنة عبر AnkiWeb مجانية وتلقائية. أنشئ بطاقاتك على الكمبيوتر وراجعها على الموبايل."}, {"q": "هل في محتوى جاهز لطلاب الطب والعلوم؟", "a": "أيوه، في مكتبة ضخمة جداً. AnKing وحده يغطي كل مادة طب USMLE بآلاف البطاقات المجانية."}]', 'تحسينات على خوارزمية FSRS الجديدة لتحسين توقيت المراجعات، تحديث واجهة إنشاء البطاقات، إصلاح مشاكل مزامنة AnkiWeb، تحسين أداء الصوت في البطاقات الصوتية.',
  'تحميل أنكي درويد للأندرويد - تطبيق الحفظ الذكي بالبطاقات', 'حمّل أنكي درويد للأندرويد مجاناً. أفضل تطبيق حفظ وتعلم بخوارزمية Spaced Repetition العلمية للطلاب والمتعلمين.', 'أنكي درويد, AnkiDroid, بطاقات تعليمية, Spaced Repetition, حفظ ذكي, تطبيق الدراسة',
  4.6, 65233, 111441, 'published', 'مجاني',
  NOW() - INTERVAL 273 DAY, NOW() - INTERVAL 22 DAY
);

